const themes = [{"title": "Introduction à la pharmacologie", "questions": [{"id": 1, "text": "La pharmacologie étudie :", "options": ["Uniquement la fabrication des boîtes de médicaments.", "Uniquement les techniques chirurgicales.", "Leurs effets sur l'organisme.", "Les médicaments.", "Leurs mécanismes d'action."], "answers": ["C", "D", "E"], "explanation": "Elle étudie les médicaments, leur action, leurs effets et leur utilisation."}, {"id": 2, "text": "Un médicament peut avoir une fonction :", "options": ["Purement décorative, sans utilisation médicale.", "Une fonction garantissant l'absence de tout effet indésirable.", "Préventive.", "Exclusivement symptomatique.", "Curative."], "answers": ["C", "E"], "explanation": "Les médicaments ont différentes fonctions, pas seulement symptomatiques."}, {"id": 3, "text": "Concernant la composition d'un médicament :", "options": ["Le principe actif est la boîte extérieure.", "L'excipient est toujours la substance produisant l'effet thérapeutique.", "La forme galénique est la forme pharmaceutique finale.", "Un excipient peut faciliter la conservation.", "Le principe actif produit l'effet thérapeutique."], "answers": ["C", "D", "E"], "explanation": "Principe actif, excipients et forme galénique ont des rôles différents."}, {"id": 4, "text": "Quelles propositions sont des formes galéniques ?", "options": ["Comprimé.", "Sirop.", "Dénomination commune internationale.", "Gélule.", "L'autorisation de mise sur le marché."], "answers": ["A", "B", "D"], "explanation": "La DCI désigne la substance active et non sa forme."}, {"id": 5, "text": "Concernant les dénominations :", "options": ["Nom commercial et DCI sont toujours identiques.", "La DCI est obligatoirement le nom du laboratoire fabricant.", "Un médicament peut avoir un nom chimique.", "Paracétamol est une DCI.", "Doliprane est un nom de spécialité."], "answers": ["C", "D", "E"], "explanation": "La DCI identifie la substance ; le nom de spécialité identifie le produit commercial."}, {"id": 6, "text": "Concernant le conditionnement :", "options": ["L'ampoule est un conditionnement primaire.", "Le blister est un conditionnement primaire.", "Le conditionnement secondaire est le principe actif.", "La boîte extérieure est un conditionnement secondaire.", "Le conditionnement secondaire est directement injecté au patient."], "answers": ["A", "B", "D"], "explanation": "Le conditionnement primaire est directement au contact du médicament."}, {"id": 7, "text": "Avant une administration, l'IDE doit vérifier :", "options": ["L'indication.", "La voie d'administration peut être changée librement par l'IDE.", "Les interactions sont impossibles si le médicament est prescrit.", "Uniquement la couleur du comprimé.", "La posologie et la voie."], "answers": ["A", "E"], "explanation": "Ces vérifications participent à la sécurité de l'administration."}, {"id": 8, "text": "Quelles associations sont correctes ?", "options": ["Vaccin : fonction préventive.", "Insuline remplaçant une sécrétion insuffisante : substitutive.", "Traitement symptomatique : suppression obligatoire de la cause.", "Produit de contraste : fonction substitutive de l'insuline.", "Produit de contraste : diagnostique."], "answers": ["A", "B", "E"], "explanation": "Un traitement symptomatique n'agit pas nécessairement sur la cause."}]}, {"title": "Pharmacocinétique", "questions": [{"id": 9, "text": "La pharmacocinétique correspond :", "options": ["Uniquement au ressenti du patient, sans étude des concentrations.", "Au devenir du médicament dans l'organisme.", "À ce que l'organisme fait au médicament.", "À l'étude de l'absorption et de l'élimination.", "Uniquement à l'effet sur les récepteurs."], "answers": ["B", "C", "D"], "explanation": "Les effets sur les récepteurs relèvent surtout de la pharmacodynamie."}, {"id": 10, "text": "Que signifie ADME ?", "options": ["Absorption.", "Déshydratation.", "Myocardite.", "Électrocardiographie.", "Activation, digestion, mouvement, expiration."], "answers": ["A"], "explanation": "ADME résume les quatre grandes étapes pharmacocinétiques."}, {"id": 11, "text": "L'absorption :", "options": ["Dépend de la voie d'administration.", "Est la transformation hépatique.", "Correspond à la disparition du médicament dans les urines.", "Dépend des propriétés du médicament.", "Est le passage du médicament vers la circulation sanguine."], "answers": ["A", "D", "E"], "explanation": "La transformation hépatique correspond au métabolisme."}, {"id": 12, "text": "La distribution :", "options": ["Ne commence qu'après l'élimination complète du médicament.", "S'effectue notamment par le sang.", "Est indépendante des propriétés du médicament.", "Est la répartition dans les tissus.", "Correspond uniquement à la fabrication du médicament."], "answers": ["B", "D"], "explanation": "Les propriétés du médicament influencent sa répartition."}, {"id": 13, "text": "Concernant le métabolisme :", "options": ["Les enzymes CYP450 peuvent intervenir.", "Il transforme le médicament.", "Se déroule exclusivement dans la vessie.", "Il ne produit que des métabolites inactifs.", "Le foie joue souvent un rôle majeur."], "answers": ["A", "B", "E"], "explanation": "Les métabolites peuvent être actifs ou inactifs."}, {"id": 14, "text": "L'excrétion peut s'effectuer :", "options": ["Par la bile pour certains médicaments.", "Uniquement par le foie.", "Uniquement par les cheveux.", "Par les reins.", "Par les urines."], "answers": ["A", "D", "E"], "explanation": "Il existe plusieurs voies d'excrétion."}, {"id": 15, "text": "La demi-vie correspond :", "options": ["À la durée de conservation de la boîte.", "Au temps pour éliminer obligatoirement tout le médicament.", "À un paramètre lié à la vitesse d'élimination.", "À un paramètre utile pour comprendre la fréquence des prises.", "Au temps pour diviser la concentration plasmatique par deux."], "answers": ["C", "D", "E"], "explanation": "Après une demi-vie, la concentration n'est pas nulle : elle est divisée par deux."}, {"id": 16, "text": "Concernant la biodisponibilité :", "options": ["Elle décrit la fraction atteignant la circulation systémique.", "Elle est identique pour toutes les voies.", "La biodisponibilité correspond au poids de la boîte.", "Le premier passage hépatique peut la réduire par voie orale.", "Elle est de 100 % par voie IV."], "answers": ["A", "D", "E"], "explanation": "La voie et le premier passage influencent la biodisponibilité."}, {"id": 17, "text": "Une insuffisance rénale peut :", "options": ["Favoriser leur accumulation.", "Rendre les doses identiques pour tous les patients.", "Diminuer l'excrétion de certains médicaments.", "Accélérer systématiquement leur élimination.", "Éliminer tout risque d'accumulation."], "answers": ["A", "C"], "explanation": "L'adaptation dépend du médicament et de la fonction rénale."}, {"id": 18, "text": "Quels facteurs modifient la pharmacocinétique ?", "options": ["Aucun facteur individuel.", "La couleur de la boîte détermine la vitesse d'élimination.", "La fonction hépatique.", "La fonction rénale.", "L'âge."], "answers": ["C", "D", "E"], "explanation": "Le devenir d'un médicament varie selon le patient."}]}, {"title": "Pharmacodynamie", "questions": [{"id": 19, "text": "La pharmacodynamie étudie :", "options": ["Les effets du médicament.", "Ce que le médicament fait à l'organisme.", "Uniquement les conditions de stockage en pharmacie.", "Uniquement l'excrétion urinaire.", "Les mécanismes d'action."], "answers": ["A", "B", "E"], "explanation": "L'excrétion appartient à la pharmacocinétique."}, {"id": 20, "text": "Un médicament peut agir sur :", "options": ["Uniquement l'emballage.", "Une étiquette sans effet biologique.", "Un récepteur membranaire.", "Exclusivement les globules rouges.", "Une cible nécessairement extérieure à l'organisme."], "answers": ["C"], "explanation": "Les cibles moléculaires sont variées."}, {"id": 21, "text": "Un agoniste :", "options": ["Active le récepteur.", "Se fixe sur un récepteur.", "Déclenche une réponse biologique.", "Est nécessairement un antagoniste.", "N'active jamais le récepteur auquel il se fixe."], "answers": ["A", "B", "C"], "explanation": "Un agoniste possède une capacité d'activation du récepteur."}, {"id": 22, "text": "Un antagoniste récepteur :", "options": ["Produit nécessairement le même effet que l'agoniste.", "Peut empêcher l'action d'un agoniste.", "Est défini par son élimination rénale.", "Est nécessairement éliminé avant de pouvoir agir.", "Peut se fixer sans activer le récepteur."], "answers": ["B", "E"], "explanation": "L'antagonisme décrit une action pharmacodynamique."}, {"id": 23, "text": "Concernant la relation dose-effet :", "options": ["La dose n'a jamais d'influence sur l'effet.", "Un plateau peut être atteint.", "Doubler la dose double toujours l'effet.", "Emax est l'effet maximal.", "L'effet peut augmenter avec la dose."], "answers": ["B", "D", "E"], "explanation": "La relation n'est pas toujours proportionnelle."}, {"id": 24, "text": "Une marge thérapeutique étroite signifie :", "options": ["Faible distance entre concentrations efficaces et toxiques.", "Possibilité d'augmenter librement les doses.", "Absence de risque de surdosage.", "Surveillance renforcée.", "Vigilance sur les interactions."], "answers": ["A", "D", "E"], "explanation": "Une marge étroite impose un emploi rigoureux."}, {"id": 25, "text": "La tolérance médicamenteuse :", "options": ["Peut impliquer une désensibilisation des récepteurs.", "Signifie obligatoirement une allergie.", "Peut suivre des administrations répétées.", "Est strictement synonyme de dépendance.", "Est une baisse d'effet pour une même dose."], "answers": ["A", "C", "E"], "explanation": "Tolérance, dépendance et allergie sont distinctes."}, {"id": 26, "text": "Concernant la dépendance :", "options": ["L'arrêt brutal est toujours sans conséquence.", "L'arrêt brutal ne peut jamais provoquer de sevrage.", "Les opioïdes peuvent entraîner une dépendance physique.", "Les benzodiazépines peuvent entraîner une dépendance.", "Une dépendance physique peut entraîner un sevrage."], "answers": ["C", "D", "E"], "explanation": "L'arrêt doit être encadré lorsqu'un risque de sevrage existe."}, {"id": 27, "text": "Alcool et benzodiazépines peuvent provoquer :", "options": ["Une protection certaine contre les effets des opioïdes.", "Une amélioration systématique de la vigilance.", "Une suppression garantie de la somnolence.", "Une majoration de la sédation.", "Une somnolence excessive."], "answers": ["D", "E"], "explanation": "Les effets dépresseurs peuvent se renforcer."}, {"id": 28, "text": "Pour rechercher des interactions, connaître :", "options": ["Les médicaments prescrits.", "La couleur des chaussures détermine les interactions.", "La consommation d'alcool.", "L'automédication.", "Uniquement le dernier médicament prescrit."], "answers": ["A", "C", "D"], "explanation": "Il faut considérer l'ensemble des produits consommés."}]}, {"title": "Pression artérielle", "questions": [{"id": 29, "text": "La pression artérielle :", "options": ["Est indépendante du système nerveux.", "Est influencée par le volume sanguin.", "Dépend du fonctionnement cardiaque.", "Est la pression du sang sur la paroi artérielle.", "Correspond uniquement au nombre de globules rouges."], "answers": ["B", "C", "D"], "explanation": "Le système nerveux participe à sa régulation."}, {"id": 30, "text": "Concernant le cycle cardiaque :", "options": ["PAS : pression abdominale superficielle.", "PAD : pression auriculaire droite.", "La diastole est une phase de contraction ventriculaire.", "Systole : contraction.", "Systole et diastole sont la même phase."], "answers": ["D"], "explanation": "Ces deux phases alternent au cours du cycle."}, {"id": 31, "text": "Toutes choses égales par ailleurs :", "options": ["La vasodilatation diminue les résistances.", "La vasodilatation diminue le diamètre vasculaire.", "La vasoconstriction élargit les vaisseaux.", "L'augmentation de volémie peut augmenter la PA.", "La vasoconstriction augmente les résistances."], "answers": ["A", "D", "E"], "explanation": "Le stress peut activer le système sympathique."}, {"id": 32, "text": "Les barorécepteurs :", "options": ["Participent à la régulation de la PA.", "Mesurent exclusivement la glycémie.", "Fabriquent les globules rouges.", "Sont présents dans les régions carotidiennes et aortiques.", "Sont les cellules qui sécrètent l'EPO."], "answers": ["A", "D"], "explanation": "Ils transmettent une information permettant d'ajuster la réponse cardiovasculaire."}, {"id": 33, "text": "Une baisse de PA peut déclencher :", "options": ["Une hausse de contractilité.", "Une augmentation garantie de la filtration rénale quelle que soit la gravité.", "La disparition immédiate du volume sanguin.", "Une activation sympathique.", "Une hausse de fréquence cardiaque."], "answers": ["A", "D", "E"], "explanation": "Ces réponses contribuent à restaurer la pression."}, {"id": 34, "text": "Pour mesurer correctement la PA :", "options": ["Brassard adapté.", "Patient au repos.", "Le brassard doit toujours être placé sur un vêtement épais.", "Patient parlant pendant toute la mesure.", "Bras soutenu au niveau du cœur."], "answers": ["A", "B", "E"], "explanation": "Position et calme influencent la fiabilité de la mesure."}, {"id": 35, "text": "Lors d'une mesure auscultatoire chez l'adulte :", "options": ["Premier bruit de Korotkoff : PAS.", "Les valeurs sont exprimées en degrés Celsius.", "Tracer les deux valeurs.", "Premier bruit : toujours PAD.", "Disparition des bruits : habituellement PAD."], "answers": ["A", "C", "E"], "explanation": "Le premier bruit indique la pression systolique."}, {"id": 36, "text": "Une PA de 120/80 mmHg donne une pression pulsée de :", "options": ["La différence PAS moins PAD.", "40 mmHg.", "La somme PAS plus PAD.", "200 mmHg.", "80 mmHg."], "answers": ["A", "B"], "explanation": "120 - 80 = 40 mmHg."}]}, {"title": "Insuffisance cardiaque", "questions": [{"id": 37, "text": "L'insuffisance cardiaque correspond :", "options": ["À un arrêt cardiaque permanent.", "Signifie obligatoirement que toutes les artères coronaires sont normales.", "À une affection toujours sans symptômes.", "À une maladie pouvant entraîner une congestion.", "À un débit insuffisant pour les besoins."], "answers": ["D", "E"], "explanation": "Le cœur continue à battre mais son fonctionnement est insuffisant."}, {"id": 38, "text": "La triade clinique comprend :", "options": ["Fatigue.", "Surdité.", "Œdèmes.", "Dyspnée.", "Fracture."], "answers": ["A", "C", "D"], "explanation": "Dyspnée, fatigue et œdèmes sont les trois signes mis en avant."}, {"id": 39, "text": "Les causes possibles comprennent :", "options": ["Le groupe sanguin, à lui seul, est toujours la cause de l'IC.", "Valvulopathie.", "Maladie coronaire.", "HTA.", "La couleur des yeux."], "answers": ["B", "C", "D"], "explanation": "Plusieurs atteintes peuvent altérer la fonction cardiaque."}, {"id": 40, "text": "Concernant la NYHA :", "options": ["IV : réservé aux patients sans aucun symptôme.", "I : pas de limitation de l'activité habituelle.", "Elle dépend uniquement de la température.", "III : aucune limitation physique.", "II : symptômes obligatoires au repos sans aucune activité."], "answers": ["B"], "explanation": "La NYHA décrit le retentissement fonctionnel."}, {"id": 41, "text": "Concernant la FEVG :", "options": ["La FEVG est le nombre de battements par minute.", "Réduite si ≤ 40 %.", "Fraction d'éjection du ventricule gauche.", "Une FEVG préservée exclut toute IC.", "Modérément réduite entre 41 et 49 %."], "answers": ["B", "C", "E"], "explanation": "L'IC peut exister avec une FEVG préservée."}, {"id": 42, "text": "La baisse du débit cardiaque peut entraîner :", "options": ["Une suppression systématique du système sympathique.", "Amélioration durable garantie par ces mécanismes.", "Tachycardie compensatrice.", "Une disparition immédiate de tous les œdèmes.", "Activation sympathique."], "answers": ["C", "E"], "explanation": "Les compensations peuvent devenir délétères à long terme."}, {"id": 43, "text": "L'orthopnée correspond :", "options": ["À un signe possible de congestion pulmonaire.", "À une absence de gêne respiratoire.", "À une gêne conduisant parfois à dormir redressé.", "À une douleur du mollet.", "À une dyspnée aggravée en position allongée."], "answers": ["A", "C", "E"], "explanation": "Il s'agit d'une manifestation respiratoire à rechercher."}, {"id": 44, "text": "Quels signes annoncent une décompensation ?", "options": ["Dyspnée aggravée.", "Une baisse isolée du nombre de cheveux.", "Œdèmes croissants.", "Amélioration constante de la tolérance à l'effort.", "Prise de poids rapide."], "answers": ["A", "C", "E"], "explanation": "Ces changements nécessitent un signalement et une évaluation."}, {"id": 45, "text": "Quels facteurs peuvent déclencher une décompensation ?", "options": ["Infection.", "Aucun événement extérieur.", "Arythmie.", "La simple lecture d'un ECG provoque une décompensation.", "Mauvaise observance."], "answers": ["A", "C", "E"], "explanation": "Il faut rechercher un facteur déclenchant."}, {"id": 46, "text": "La surveillance infirmière comprend :", "options": ["Le traitement peut être arrêté dès que le patient se sent mieux, sans avis médical.", "Poids et diurèse.", "Dyspnée et saturation.", "PA et fréquence cardiaque.", "La couleur de l'ordonnance remplace le suivi biologique."], "answers": ["B", "C", "D"], "explanation": "Elle associe suivi clinique, biologique et éducation."}]}, {"title": "Insuffisance coronaire", "questions": [{"id": 47, "text": "L'insuffisance coronaire correspond :", "options": ["À une affection qui ne concerne jamais l'oxygénation myocardique.", "À un excès obligatoire d'O₂ myocardique.", "À un problème exclusivement veineux des jambes.", "À un déséquilibre besoins/apports en O₂ du myocarde.", "À une possible ischémie myocardique."], "answers": ["D", "E"], "explanation": "Les apports coronaires deviennent insuffisants par rapport aux besoins."}, {"id": 48, "text": "La plaque d'athérome :", "options": ["Associe dépôts lipidiques et inflammation.", "Élargit systématiquement l'artère.", "Est toujours sans effet sur le flux sanguin.", "Peut toucher une coronaire.", "Peut réduire la lumière artérielle."], "answers": ["A", "D", "E"], "explanation": "L'athérome peut gêner le flux et se compliquer."}, {"id": 49, "text": "Pourquoi l'effort peut-il déclencher un angor ?", "options": ["Les besoins myocardiques en O₂ augmentent.", "L'effort supprime obligatoirement toutes les sténoses coronaires.", "Un déséquilibre apport/demande peut apparaître.", "Le cœur cesse de consommer de l'O₂.", "Une sténose limite l'augmentation du débit coronaire."], "answers": ["A", "C", "E"], "explanation": "L'effort peut révéler l'insuffisance des apports."}, {"id": 50, "text": "Quels facteurs de risque sont cités ?", "options": ["L'utilisation d'un brassard provoque habituellement une plaque d'athérome.", "Une bonne hydratation est toujours un facteur majeur de sténose coronaire.", "Le port de lunettes est un facteur majeur d'athérome.", "La couleur des cheveux est une cause directe d'ischémie.", "Tabagisme."], "answers": ["E"], "explanation": "Le tabagisme est un facteur de risque cardiovasculaire ; les autres propositions présentées ne sont pas des facteurs majeurs de coronaropathie."}, {"id": 51, "text": "Concernant l'angor :", "options": ["Survient uniquement dans les veines des jambes.", "Douleur nécessairement au pied.", "Survenue possible à l'effort.", "Douleur thoracique constrictive possible.", "Certaines formes surviennent au repos."], "answers": ["C", "D", "E"], "explanation": "Le contexte et les caractéristiques de douleur orientent l'évaluation."}, {"id": 52, "text": "Quelle distinction est correcte ?", "options": ["Toute ischémie provoque immédiatement une nécrose.", "Nécrose : mort tissulaire.", "Ischémie : apport sanguin insuffisant.", "Nécrose : simple augmentation transitoire du débit sanguin.", "Ischémie et nécrose sont synonymes."], "answers": ["B", "C"], "explanation": "Une ischémie prolongée peut évoluer vers une nécrose."}]}, {"title": "Syndrome coronarien aigu et infarctus", "questions": [{"id": 53, "text": "Un syndrome coronarien aigu :", "options": ["Provoque une ischémie myocardique aiguë.", "Est toujours bénin.", "Ne peut jamais évoluer vers une lésion myocardique.", "Peut suivre une obstruction coronaire brutale.", "Peut engager le pronostic vital."], "answers": ["A", "D", "E"], "explanation": "La reconnaissance et la prise en charge doivent être rapides."}, {"id": 54, "text": "Une douleur évocatrice peut être :", "options": ["Obligatoirement limitée à une seconde.", "Constrictive, en étau.", "Persistante.", "Obligatoirement soulagée par un effort intense.", "Rétrosternale."], "answers": ["B", "C", "E"], "explanation": "Ne pas attendre une durée précise avant d'alerter."}, {"id": 55, "text": "Quelles irradiations sont citées ?", "options": ["Bras gauche.", "Aucune irradiation possible.", "Uniquement les orteils.", "Dos.", "Mâchoire."], "answers": ["A", "D", "E"], "explanation": "Ces irradiations sont possibles mais non obligatoires."}, {"id": 56, "text": "Quels signes peuvent accompagner la douleur ?", "options": ["Dyspnée.", "Nausées.", "Absence obligatoire d'autres symptômes.", "Une disparition obligatoire de tout risque cardiaque dès que la douleur diminue.", "Sueurs."], "answers": ["A", "B", "E"], "explanation": "Les manifestations associées peuvent renforcer la suspicion."}, {"id": 57, "text": "Concernant les examens :", "options": ["Les symptômes remplacent toujours tous les examens.", "Une troponine élevée désigne obligatoirement une fracture.", "Un ECG mesure directement le nombre de plaquettes.", "L'ECG contribue à l'évaluation.", "Un sus-décalage ST peut être présent."], "answers": ["D", "E"], "explanation": "Les résultats sont interprétés avec le contexte clinique."}, {"id": 58, "text": "STEMI et NSTEMI :", "options": ["Tout NSTEMI est sans nécrose.", "Peuvent tous deux être graves.", "Se distinguent notamment par le sus-décalage ST.", "Un NSTEMI ne nécessite jamais d'évaluation urgente.", "Sont des catégories d'infarctus."], "answers": ["B", "C", "E"], "explanation": "La distinction ne se résume pas à obstruction partielle ou totale."}, {"id": 59, "text": "Devant une suspicion de SCA hors de l'hôpital :", "options": ["Faire réaliser un effort pour confirmer.", "Attendre obligatoirement trente minutes.", "Appeler immédiatement le 15.", "Surveiller en attendant les secours.", "Mettre au repos."], "answers": ["C", "D", "E"], "explanation": "Alerter sans attendre et éviter l'effort."}, {"id": 60, "text": "L'objectif de la reperfusion est :", "options": ["Rétablir le flux sanguin.", "Supprimer l'irrigation du myocarde.", "Obstruer davantage l'artère.", "Augmenter volontairement la durée d'ischémie.", "Provoquer une thrombose coronaire."], "answers": ["A"], "explanation": "Le délai de reperfusion influence les dommages myocardiques."}]}, {"title": "Maladie thromboembolique veineuse", "questions": [{"id": 61, "text": "La MTEV regroupe :", "options": ["L'embolie pulmonaire.", "Uniquement les infarctus coronaires.", "Deux manifestations d'un même processus.", "La TVP.", "Uniquement les infections respiratoires."], "answers": ["A", "C", "D"], "explanation": "TVP et EP appartiennent au même ensemble pathologique."}, {"id": 62, "text": "Une TVP correspond :", "options": ["À une infection obligatoire du tissu osseux.", "À du gaz dans l'estomac.", "À une obstruction exclusivement coronaire.", "À une obstruction pouvant toucher les membres inférieurs.", "À un caillot dans une veine profonde."], "answers": ["D", "E"], "explanation": "La TVP touche le réseau veineux profond."}, {"id": 63, "text": "Quels signes évoquent une TVP du membre inférieur ?", "options": ["Une douleur nécessairement symétrique des deux poignets.", "Douleur unilatérale.", "Œdème unilatéral.", "Chaleur locale.", "Absence obligatoire de gonflement."], "answers": ["B", "C", "D"], "explanation": "Ces signes ne suffisent pas seuls à confirmer le diagnostic."}, {"id": 64, "text": "La triade de Virchow comprend :", "options": ["Hypoglycémie.", "Stase veineuse.", "Altération de la paroi vasculaire.", "Hyperventilation.", "Hypercoagulabilité."], "answers": ["B", "C", "E"], "explanation": "Ces trois mécanismes favorisent la thrombose."}, {"id": 65, "text": "Quels facteurs favorisent une MTEV ?", "options": ["Chirurgie.", "Immobilisation prolongée.", "La simple prise de température est une cause majeure de thrombose.", "Le port de lunettes est une thrombophilie.", "Cancer."], "answers": ["A", "B", "E"], "explanation": "Ils agissent par un ou plusieurs mécanismes de Virchow."}, {"id": 66, "text": "Une EP peut provoquer :", "options": ["Tachycardie.", "Une amélioration obligatoire et immédiate de l'oxygénation.", "Dyspnée brutale.", "Douleur thoracique.", "Une absence garantie de toute complication."], "answers": ["A", "C", "D"], "explanation": "La dyspnée, la douleur thoracique et la tachycardie peuvent accompagner une EP ; aucune amélioration spontanée ou absence de complication n’est garantie."}, {"id": 67, "text": "Quelles associations diagnostiques sont correctes ?", "options": ["Angioscanner pulmonaire : recherche d'EP.", "Radio du poignet : confirmation d'une TVP.", "D-dimères élevés : preuve certaine d'EP à eux seuls.", "Écho-Doppler veineux : recherche de TVP.", "D-dimères : examen permettant de localiser précisément le caillot à lui seul."], "answers": ["A", "D"], "explanation": "Les D-dimères ne sont pas spécifiques."}, {"id": 68, "text": "Concernant conséquences et traitement :", "options": ["Les anticoagulants ont une place importante.", "Une EP grave peut causer un arrêt cardiaque.", "Une EP grave peut causer un choc obstructif.", "Toute TVP impose une thrombolyse.", "Les anticoagulants entraînent toujours la dissolution instantanée du thrombus."], "answers": ["A", "B", "C"], "explanation": "Le traitement dépend notamment de la gravité et du risque hémorragique."}]}, {"title": "Physiologie respiratoire", "questions": [{"id": 69, "text": "Selon la loi de Dalton :", "options": ["Chaque gaz contribue à la pression totale.", "Pression totale = somme des pressions partielles.", "Toutes les pressions partielles sont identiques.", "La pression dépend uniquement de l'O₂.", "Elle concerne les mélanges gazeux."], "answers": ["A", "B", "E"], "explanation": "La contribution de chaque gaz dépend de sa proportion."}, {"id": 70, "text": "Au niveau de la mer, les valeurs approximatives sont :", "options": ["O₂ : 80 %.", "O₂ de l'air sec : 2,09 %.", "Pression atmosphérique : 40 mmHg.", "Pression atmosphérique : 7 600 mmHg.", "Pression atmosphérique : 760 mmHg."], "answers": ["E"], "explanation": "0,209 × 760 ≈ 159 mmHg."}, {"id": 71, "text": "En altitude :", "options": ["La pression atmosphérique diminue.", "La proportion d'O₂ devient nécessairement nulle.", "La PO₂ de l'air diminue.", "La pression atmosphérique augmente toujours quand on monte.", "L'apport d'O₂ peut devenir insuffisant."], "answers": ["A", "C", "E"], "explanation": "La proportion reste proche de 21 % mais la pression diminue."}, {"id": 72, "text": "Les adaptations à l'hypoxie comprennent :", "options": ["Fréquence cardiaque parfois accrue.", "Production instantanée de millions de globules rouges en une seconde.", "La ventilation cesse pour économiser l'oxygène.", "Ventilation accrue.", "L'EPO provoque la destruction des globules rouges."], "answers": ["A", "D"], "explanation": "L'adaptation hématologique prend plus de temps que la réponse respiratoire."}, {"id": 73, "text": "Concernant l'EPO :", "options": ["Stimule l'érythropoïèse.", "Produite principalement par le rein chez l'adulte.", "Est principalement sécrétée par les valves cardiaques.", "Détruit normalement l'hémoglobine.", "Érythropoïétine."], "answers": ["A", "B", "E"], "explanation": "L'EPO stimule la production érythrocytaire dans la moelle osseuse."}, {"id": 74, "text": "Concernant le transport de l'O₂ :", "options": ["La majorité est liée à l'hémoglobine.", "L'hémoglobine est située uniquement dans les plaquettes.", "L'O₂ est uniquement dissous.", "Une petite fraction est dissoute.", "Une hémoglobine peut fixer quatre molécules d'O₂."], "answers": ["A", "D", "E"], "explanation": "Le support présente environ 98 % lié et 2 % dissous."}, {"id": 75, "text": "Selon la loi de Henry, à température constante :", "options": ["La pression n'a aucun effet.", "Une pression partielle plus élevée favorise la dissolution.", "L'azote se dissout davantage sous pression en plongée.", "La dissolution des gaz dépend uniquement de la couleur du liquide.", "La dissolution dépend de la pression partielle."], "answers": ["B", "C", "E"], "explanation": "Pression partielle et propriétés du gaz et du liquide interviennent."}, {"id": 76, "text": "Concernant l'accident de décompression :", "options": ["La chute rapide de pression peut favoriser des bulles d'azote.", "Une remontée rapide empêche toujours la formation de bulles.", "Douleurs articulaires possibles.", "Troubles neurologiques possibles.", "Il est toujours bénin."], "answers": ["A", "C", "D"], "explanation": "Les bulles peuvent provoquer des atteintes graves."}]}, {"title": "Notions de microbiologie : monde du vivant et agents infectieux", "description": "B.1.a · S1 · 20 QCM corrigés", "courseId": "b1-microbiologie", "questions": [{"text": "Les cellules procaryotes se caractérisent notamment par :", "options": ["Un ADN non enfermé dans un noyau.", "Un noyau entouré d’une enveloppe comme dans une cellule humaine typique.", "L’absence obligatoire de toute membrane.", "Leur appartenance possible au groupe des bactéries.", "La présence de ribosomes."], "answers": ["A", "D", "E"], "explanation": "Les procaryotes ont des structures cellulaires, mais pas de noyau délimité. Les bactéries et archées en font partie ; elles ne sont pas dépourvues de membrane ou de ribosomes.", "id": 2500}, {"text": "Quelles entités sont eucaryotes ?", "options": ["Une cellule humaine typique.", "Une bactérie E. coli.", "Une levure.", "Un virus de la grippe.", "Un protozoaire."], "answers": ["A", "C", "E"], "explanation": "Humain, levure et protozoaire ont des cellules eucaryotes. Une bactérie est procaryote ; un virus est acellulaire.", "id": 2501}, {"text": "Concernant les virus :", "options": ["Ils sont tous des bactéries Gram négatif.", "Ils dépendent d’une cellule hôte pour se multiplier.", "Ils possèdent une capside.", "Ils ont tous une enveloppe.", "Ils possèdent un génome ADN ou ARN selon le virus."], "answers": ["B", "C", "E"], "explanation": "Le virus utilise un hôte et possède génome et capside. L’enveloppe n’est pas universelle et la coloration de Gram ne classe pas les virus.", "id": 2502}, {"text": "Un prion est :", "options": ["Une levure.", "Un agent infectieux lié à une protéine anormalement conformée.", "Un virus contenant toujours de l’ADN.", "Un globule blanc.", "Une bactérie encapsulée."], "answers": ["B"], "explanation": "Les prions sont des agents distincts des cellules et virus. Leur nature protéique est le repère essentiel ici.", "id": 2503}, {"text": "Coque et bacille décrivent :", "options": ["Des éléments utiles mais insuffisants pour identifier une bactérie.", "Une forme arrondie et une forme allongée.", "Des formes de bactéries.", "À eux seuls la gravité d’une infection.", "À eux seuls l’espèce bactérienne précise."], "answers": ["A", "B", "C"], "explanation": "La morphologie donne un repère, pas une identification complète. Plusieurs espèces peuvent partager une forme et avoir des propriétés différentes.", "id": 2504}, {"text": "La coloration de Gram :", "options": ["Permet de parler de Gram positif et Gram négatif.", "Distingue des propriétés de l’enveloppe bactérienne.", "Sépare directement toutes les bactéries dangereuses de toutes les inoffensives.", "Identifie toujours à elle seule l’espèce.", "N’est pas une classification des virus."], "answers": ["A", "B", "E"], "explanation": "Gram décrit un comportement de coloration lié à l’enveloppe. Il ne mesure pas directement la dangerosité et ne remplace pas l’identification.", "id": 2505}, {"text": "La croissance bactérienne dépend notamment :", "options": ["De la température.", "De la présence obligatoire de lumière chez toutes les espèces.", "Des nutriments disponibles.", "D’une température identique obligatoire pour toutes les bactéries.", "Des besoins en oxygène propres à l’espèce."], "answers": ["A", "C", "E"], "explanation": "Les conditions varient selon les espèces. Toutes les bactéries ne partagent ni mêmes besoins en oxygène ni même température optimale.", "id": 2506}, {"text": "Une endospore bactérienne :", "options": ["Peut être une forme résistante de survie.", "N’est pas un mode de multiplication par elle-même.", "Est identique à une hématie.", "Est produite par certaines espèces seulement.", "Permet obligatoirement de doubler le nombre de bactéries à chaque formation."], "answers": ["A", "B", "D"], "explanation": "L’endospore permet à certaines bactéries de persister dans des conditions défavorables. Sa formation n’augmente pas le nombre de bactéries.", "id": 2507}, {"text": "Les champignons comprennent notamment :", "options": ["Toutes les bactéries Gram positif.", "Tous les virus enveloppés.", "Des moisissures.", "Des levures.", "Candida."], "answers": ["C", "D", "E"], "explanation": "Levures et moisissures sont des champignons eucaryotes. Candida est une levure et peut être impliqué dans des mycoses.", "id": 2508}, {"text": "Concernant les parasites :", "options": ["Plasmodium est un parasite responsable du paludisme.", "Tous leurs stades sont forcément microscopiques.", "Ils comprennent des protozoaires et des helminthes.", "L’acarien de la gale est un ectoparasite.", "Le moustique et Plasmodium désignent le même organisme."], "answers": ["A", "C", "D"], "explanation": "La parasitologie couvre des organismes variés. Dans le paludisme, le moustique est le vecteur et Plasmodium l’agent ; la gale implique un acarien.", "id": 2509}, {"text": "Le microbiote :", "options": ["Est toujours une infection nécessitant un antibiotique.", "Est composé uniquement de virus.", "Peut contribuer à des fonctions protectrices et métaboliques.", "Rassemble les micro-organismes d’un milieu.", "Peut contenir des organismes devenant pathogènes dans un autre contexte."], "answers": ["C", "D", "E"], "explanation": "La présence habituelle de micro-organismes n’est pas une infection en soi. Leur effet dépend notamment du site et des défenses de l’hôte.", "id": 2510}, {"text": "La colonisation correspond généralement à :", "options": ["Une présence et multiplication sans infection établie.", "Une preuve que la transmission est impossible.", "Une notion distincte d’infection.", "Une situation pouvant être sans symptômes.", "Une indication automatique d’antibiotique."], "answers": ["A", "C", "D"], "explanation": "Colonisation et infection ne sont pas synonymes. L’absence de maladie établie ne permet pas d’affirmer une absence de transmission.", "id": 2511}, {"text": "Un prélèvement positif :", "options": ["Peut correspondre à une contamination du prélèvement.", "Impose toujours un antibiotique immédiatement.", "Prouve toujours une maladie symptomatique.", "Peut refléter une colonisation.", "Doit être interprété avec le site et la situation clinique."], "answers": ["A", "D", "E"], "explanation": "Le résultat de laboratoire ne suffit pas seul. Qualité du prélèvement, site et contexte permettent de distinguer contamination, colonisation et infection.", "id": 2512}, {"text": "Une inflammation :", "options": ["Est exclue dès qu’il n’y a pas de fièvre.", "Peut accompagner une lésion sans bactérie responsable.", "Peut être non infectieuse.", "Est toujours une infection bactérienne.", "Peut être liée à une infection."], "answers": ["B", "C", "E"], "explanation": "L’inflammation est une réponse pouvant avoir plusieurs causes. La fièvre n’est ni obligatoire dans toute inflammation ni une preuve spécifique de bactérie.", "id": 2513}, {"text": "Une chaîne de transmission comporte notamment :", "options": ["Un réservoir ou une source.", "Un mode de transmission.", "Une absence obligatoire de porte de sortie.", "Une multiplication obligatoire dans un médicament.", "Une porte d’entrée et un hôte réceptif."], "answers": ["A", "B", "E"], "explanation": "La chaîne complète associe agent, source, sortie, mode, entrée et hôte. Interrompre un maillon peut réduire la transmission.", "id": 2514}, {"text": "Une transmission par contact peut être :", "options": ["Indirecte via du matériel contaminé.", "Impossible si le patient ne présente pas de fièvre.", "Exclusivement liée à l’inhalation de particules.", "Directe entre personnes.", "Indirecte via les mains."], "answers": ["A", "D", "E"], "explanation": "Contact direct et indirect sont distincts des voies respiratoires. Des transmissions sont possibles sans fièvre ou sans symptômes selon l’agent.", "id": 2515}, {"text": "Concernant les antibiotiques :", "options": ["Ils remplacent toujours la vaccination.", "Ils traitent automatiquement toute infection virale.", "L’efficacité dépend notamment de la bactérie et de sa sensibilité.", "Leur usage inapproprié peut sélectionner des résistances.", "Ils ciblent des mécanismes bactériens."], "answers": ["C", "D", "E"], "explanation": "Les antibiotiques ne sont pas des traitements universels des infections. Sensibilité et bon usage comptent pour efficacité et maîtrise des résistances.", "id": 2516}, {"text": "Une bactérie multirésistante :", "options": ["Possède une résistance à plusieurs antibiotiques selon les critères utilisés.", "Est forcément plus virulente que toute bactérie sensible.", "N’annule pas la nécessité de prévention des transmissions.", "Signifie simplement que le patient est habitué au médicament.", "Peut compliquer le choix d’un traitement."], "answers": ["A", "C", "E"], "explanation": "Résistance et virulence sont des notions différentes. La résistance appartient aux mécanismes de la bactérie et peut réduire les options thérapeutiques.", "id": 2517}, {"text": "Un biofilm :", "options": ["Associe une communauté microbienne et une matrice.", "Peut se former sur des dispositifs.", "Ne concerne jamais le matériel de soins.", "Est une preuve que toute surface a été stérilisée.", "Peut compliquer l’élimination des micro-organismes."], "answers": ["A", "B", "E"], "explanation": "Le biofilm est une organisation de micro-organismes sur une surface. Il peut concerner des dispositifs et rendre le traitement plus difficile.", "id": 2518}, {"text": "Pour prévenir les infections :", "options": ["L’hygiène des mains interrompt certaines transmissions.", "La vaccination protège contre certains agents ciblés.", "L’entretien adapté du matériel est utile.", "La vaccination dispense de toutes les précautions standard.", "Un patient sans symptômes ne transmet jamais aucun agent."], "answers": ["A", "B", "C"], "explanation": "Les mesures se complètent. Aucune vaccination ne protège contre tous les agents ; certaines transmissions proviennent de personnes sans symptômes.", "id": 2519}], "overview": [["Repère 1", "Bactéries : procaryotes ; champignons et protozoaires : eucaryotes ; virus : acellulaires."], ["Repère 2", "Forme et Gram sont des repères, pas une identification complète."], ["Repère 3", "Contamination, colonisation et infection ne sont pas synonymes."], ["Repère 4", "Inflammation ne signifie pas nécessairement infection."], ["Repère 5", "Prévention = interrompre la chaîne de transmission."]], "references": [{"title": "OpenStax · Micro-organismes", "url": "https://openstax.org/books/microbiology/pages/1-3-types-of-microorganisms"}, {"title": "OpenStax · Procaryotes", "url": "https://openstax.org/books/microbiology/pages/3-3-unique-characteristics-of-prokaryotic-cells"}, {"title": "OpenStax · Virus", "url": "https://openstax.org/books/microbiology/pages/6-1-viruses"}, {"title": "OpenStax · Infections", "url": "https://openstax.org/books/microbiology/pages/15-1-characteristics-of-infectious-disease"}, {"title": "OpenStax · Transmission", "url": "https://openstax.org/books/microbiology/pages/16-3-modes-of-disease-transmission"}]}, {"title": "Notions de base de biochimie ou chimie du vivant", "description": "B.1.a · S1 · 20 QCM corrigés", "courseId": "b1-chimie", "questions": [{"text": "Un atome neutre de carbone possède 6 protons. Que peut-on affirmer ?", "options": ["Il porte nécessairement une charge positive.", "Il possède nécessairement 6 neutrons.", "Son numéro atomique est 6.", "Son élément est défini par ses protons.", "Il possède 6 électrons."], "answers": ["C", "D", "E"], "explanation": "Dans un atome neutre, protons et électrons sont aussi nombreux. Z est le nombre de protons. Le nombre de neutrons dépend de l’isotope et ne se déduit pas de la neutralité.", "id": 2000}, {"text": "Un noyau possède 8 protons et 10 neutrons. Quelles valeurs sont justes ?", "options": ["A = 18.", "A = 8.", "A = 2.", "Z = 8.", "Z = 10."], "answers": ["A", "D"], "explanation": "Z = 8 protons ; A = 8 + 10 = 18 nucléons. Le nombre de masse n’est pas le nombre d’électrons.", "id": 2001}, {"text": "Deux isotopes d’un même élément diffèrent par :", "options": ["Leur nom d’élément.", "Le fait que l’un soit toujours une molécule.", "Leur nombre de protons.", "Leur nombre de neutrons.", "Leur numéro atomique."], "answers": ["D"], "explanation": "Les isotopes ont le même nombre de protons, donc le même élément, mais des nombres de neutrons différents. Ils ne sont pas tous radioactifs.", "id": 2002}, {"text": "Lorsqu’un atome perd un électron sans modifier son noyau :", "options": ["Il peut devenir un cation.", "Il devient plus positif.", "Son nombre de protons change.", "Il devient plus négatif.", "Il devient nécessairement un autre élément."], "answers": ["A", "B"], "explanation": "Un électron porte une charge négative : sa perte augmente la charge nette. Un atome initialement neutre devient alors un cation, sans changer d’élément.", "id": 2003}, {"text": "Quelles espèces sont des cations ?", "options": ["Ca²⁺.", "Cl⁻.", "K⁺.", "HCO₃⁻.", "Na⁺."], "answers": ["A", "C", "E"], "explanation": "Les signes positifs identifient les cations ; Na⁺, Ca²⁺ et K⁺ en sont. Cl⁻ et HCO₃⁻ sont des anions.", "id": 2004}, {"text": "Une liaison covalente correspond à :", "options": ["La présence obligatoire d’une charge positive globale.", "Un transfert de cellules.", "La transformation d’un proton en neutron.", "Un partage d’électrons.", "Une absence de toute interaction entre atomes."], "answers": ["D"], "explanation": "Une liaison covalente implique un partage d’électrons. Elle peut exister dans une molécule neutre ; la charge globale n’est pas son critère de définition.", "id": 2005}, {"text": "Concernant les molécules et les composés :", "options": ["H₂O comporte deux atomes d’oxygène et un hydrogène.", "Le NaCl solide forme un réseau ionique.", "Une molécule comporte toujours deux éléments différents.", "O₂ et H₂O sont des molécules.", "O₂ comporte deux atomes d’oxygène."], "answers": ["B", "D", "E"], "explanation": "O₂ contient deux atomes du même élément. H₂O contient deux hydrogènes et un oxygène. Le cristal de NaCl est un réseau d’ions, pas un ensemble de molécules isolées de NaCl.", "id": 2006}, {"text": "Les liaisons hydrogène participent notamment :", "options": ["À l’organisation de certaines protéines.", "À certaines interactions stabilisant l’ADN.", "À la transformation du sodium en carbone.", "À la création de tous les noyaux atomiques.", "Aux interactions entre molécules d’eau."], "answers": ["A", "B", "E"], "explanation": "Ces interactions contribuent aux propriétés de l’eau et à l’organisation de macromolécules. Elles ne modifient pas les noyaux des éléments.", "id": 2007}, {"text": "L’eau dans l’organisme :", "options": ["Participe à la régulation thermique.", "Est toujours présente à exactement 60 % chez chacun.", "Est un triglycéride.", "Permet le transport de nombreuses substances.", "Est un solvant important."], "answers": ["A", "D", "E"], "explanation": "L’eau a des rôles de solvant, transport et thermorégulation. Sa proportion dépend notamment de l’âge et de la composition corporelle ; elle n’est pas identique chez tous.", "id": 2008}, {"text": "Concernant la répartition ionique habituelle :", "options": ["Le calcium peut intervenir dans la contraction.", "Le potassium est un cation majeur du milieu intracellulaire.", "Tous les ions ont exactement la même concentration de part et d’autre d’une membrane.", "Le sodium est un cation majeur du milieu extracellulaire.", "Le chlorure est une molécule de protéine."], "answers": ["A", "B", "D"], "explanation": "Des gradients ioniques existent. Sodium et potassium ont des répartitions différentes ; calcium et autres ions participent à des fonctions spécifiques.", "id": 2009}, {"text": "Pour une solution aqueuse à 25 °C :", "options": ["Une baisse du pH de 6 à 5 correspond à une activité H⁺ multipliée par 10.", "Une unité de pH correspond toujours à une simple addition de 1 à la concentration H⁺.", "Un pH de 7 est neutre.", "Un pH de 4 est plus acide qu’un pH de 6.", "Un pH de 9 est plus acide qu’un pH de 4."], "answers": ["A", "C", "D"], "explanation": "Le pH est logarithmique. Une baisse d’une unité multiplie l’activité H⁺ par 10 ; à 25 °C, le pH neutre est 7.", "id": 2010}, {"text": "Concernant l’équilibre acido-basique :", "options": ["Les systèmes tampons limitent les variations de pH.", "Le contenu gastrique possède obligatoirement le même pH que le sang.", "Les poumons et les reins y participent.", "Tous les compartiments ont un pH neutre.", "Le pH sanguin artériel habituel se situe autour de 7,35–7,45."], "answers": ["A", "C", "E"], "explanation": "Les tampons, la ventilation et les fonctions rénales contribuent à la régulation. La plage sanguine ne s’applique pas à tous les liquides du corps.", "id": 2011}, {"text": "Quels exemples correspondent à des glucides ?", "options": ["Un anticorps.", "Un triglycéride.", "Le glycogène.", "Le glucose.", "L’hémoglobine."], "answers": ["C", "D"], "explanation": "Le glucose est un ose et le glycogène un assemblage de glucose servant de réserve. Triglycéride est un lipide ; hémoglobine et anticorps sont des protéines.", "id": 2012}, {"text": "Quelles associations concernant les lipides sont exactes ?", "options": ["Cholestérol : précurseur de certaines hormones.", "Les lipides n’ont aucune fonction structurale.", "Phospholipides : constituants des membranes.", "Tous les lipides sont des chaînes d’acides aminés.", "Triglycérides : réserve énergétique."], "answers": ["A", "C", "E"], "explanation": "Les lipides ont plusieurs rôles : réserve, membranes et précurseurs. Les chaînes d’acides aminés caractérisent les protéines, pas les lipides.", "id": 2013}, {"text": "Une protéine :", "options": ["Peut avoir une fonction de transport.", "Ne dépend jamais de sa forme pour fonctionner.", "Contient des liaisons peptidiques.", "Est toujours un acide nucléique.", "Est constituée d’acides aminés."], "answers": ["A", "C", "E"], "explanation": "Les protéines sont des assemblages d’acides aminés. Leur forme peut être essentielle à leur fonction, par exemple pour un transporteur ou une enzyme.", "id": 2014}, {"text": "Une enzyme :", "options": ["Remplace l’information génétique.", "Supprime toute nécessité de conditions adaptées.", "Est toujours le substrat qu’elle détruit.", "Accélère une réaction qu’elle catalyse.", "N’est pas consommée par cette réaction."], "answers": ["D", "E"], "explanation": "Une enzyme est un catalyseur. Son efficacité dépend des conditions et de sa spécificité ; elle n’est ni le substrat ni un remplacement de l’ADN.", "id": 2015}, {"text": "Un nucléotide comporte :", "options": ["Obligatoirement une cellule entière.", "Un sucre.", "Obligatoirement une fibre de collagène.", "Un phosphate.", "Une base azotée."], "answers": ["B", "D", "E"], "explanation": "Sucre, phosphate et base constituent le nucléotide. ADN et ARN sont constitués de nucléotides.", "id": 2016}, {"text": "Quelles propositions sont exactes concernant ADN et ARN ?", "options": ["L’ADN porte une information génétique.", "ADN et ARN appartiennent aux acides nucléiques.", "L’ARN est constitué uniquement d’acides aminés.", "Les ARN participent à l’utilisation de cette information.", "ADN signifie réserve principale de triglycérides."], "answers": ["A", "B", "D"], "explanation": "ADN et ARN sont des acides nucléiques. Les ARN ont plusieurs fonctions, notamment dans l’expression des gènes ; ils ne sont pas des protéines.", "id": 2017}, {"text": "L’ATP :", "options": ["Peut être utilisé par des pompes membranaires.", "Est un nucléotide.", "Est la réserve lipidique à long terme du tissu adipeux.", "Est une hématie.", "Est un intermédiaire énergétique cellulaire."], "answers": ["A", "B", "E"], "explanation": "L’ATP participe au couplage énergétique de nombreuses activités, dont certaines pompes. La réserve lipidique du tissu adipeux correspond surtout aux triglycérides.", "id": 2018}, {"text": "Concernant le métabolisme :", "options": ["Le métabolisme regroupe les réactions cellulaires.", "L’anabolisme comprend des synthèses.", "Le catabolisme comprend des dégradations.", "Catabolisme signifie toujours fabrication d’une protéine.", "Anabolisme signifie exclusivement destruction d’un glucide."], "answers": ["A", "B", "C"], "explanation": "Anabolisme et catabolisme sont des ensembles de voies complémentaires au sein du métabolisme. Les confondre inverse synthèse et dégradation.", "id": 2019}], "overview": [["Repère 1", "Z = nombre de protons ; A = protons + neutrons."], ["Repère 2", "Cation positif, anion négatif : le signe dépend de la charge, pas de la taille."], ["Repère 3", "Eau et électrolytes appartiennent aux constituants minéraux du vivant."], ["Repère 4", "Glucides, lipides, protéines et acides nucléiques ont des rôles différents et complémentaires."], ["Repère 5", "Une enzyme catalyse ; l’ATP sert au couplage énergétique ; l’ADN porte l’information génétique."]], "references": [{"title": "OpenStax · Atomes", "url": "https://openstax.org/books/anatomy-and-physiology-2e/pages/2-1-elements-and-atoms-the-building-blocks-of-matter"}, {"title": "OpenStax · Liaisons", "url": "https://openstax.org/books/anatomy-and-physiology-2e/pages/2-2-chemical-bonds"}, {"title": "OpenStax · Constituants minéraux", "url": "https://openstax.org/books/anatomy-and-physiology-2e/pages/2-4-inorganic-compounds-essential-to-human-functioning"}, {"title": "OpenStax · Molécules organiques", "url": "https://openstax.org/books/anatomy-and-physiology-2e/pages/2-5-organic-compounds-essential-to-human-functioning"}]}, {"title": "Les différents tissus du corps humain et leurs fonctions", "description": "B.1.a · S1 · 28 QCM corrigés", "courseId": "b1-tissus", "questions": [{"id": 121, "text": "Concernant les niveaux d’organisation du corps humain :", "options": ["Un organe peut associer plusieurs types de tissus.", "Un tissu est toujours une cellule isolée.", "Plusieurs organes coopèrent au sein d’un appareil ou système.", "Les cellules participent à la constitution des tissus.", "Un tissu et un organe désignent exactement la même chose."], "answers": ["A", "C", "D"], "explanation": "Les cellules s’organisent en tissus ; plusieurs tissus constituent un organe. Des organes coopèrent dans des appareils ou systèmes, comme l’appareil digestif."}, {"id": 122, "text": "Quelles propositions désignent des familles fondamentales de tissus ?", "options": ["Le tissu épithélial.", "Le tissu digestif, comme cinquième famille fondamentale.", "Le tissu conjonctif.", "Le tissu respiratoire, comme sixième famille fondamentale.", "Le tissu nerveux."], "answers": ["A", "C", "E"], "explanation": "Les quatre grandes familles sont les tissus épithélial, conjonctif, musculaire et nerveux. Digestif et respiratoire désignent ici des appareils qui associent plusieurs tissus."}, {"id": 123, "text": "L’histologie correspond à :", "options": ["L’étude exclusive des médicaments.", "L’étude des tissus, notamment de leur organisation microscopique.", "La mesure de la seule pression artérielle.", "L’étude exclusive des os à la radiographie.", "L’étude uniquement des agents infectieux."], "answers": ["B"], "explanation": "L’histologie étudie la structure des tissus. Elle aide à comprendre le lien entre leur organisation et leur fonction."}, {"id": 124, "text": "Quelles associations fonctionnelles sont correctes ?", "options": ["Épithélium de revêtement : protection ou échanges selon sa localisation.", "Tissu musculaire : production exclusive des hormones thyroïdiennes.", "Tissu nerveux : réception et transmission de messages.", "Tissu conjonctif : soutien et liaison entre structures.", "Tissu épithélial : contraction de tous les muscles."], "answers": ["A", "C", "D"], "explanation": "Le rôle dominant aide à reconnaître la famille : revêtement et sécrétion pour l’épithélial, soutien pour le conjonctif, contraction pour le musculaire, communication pour le nerveux."}, {"id": 125, "text": "Un épithélium de revêtement présente habituellement :", "options": ["Des cellules jointives.", "Une matrice extracellulaire très abondante entre toutes ses cellules.", "Une face apicale et une face basale.", "Des cellules reposant sur une lame basale.", "Des fibres musculaires constituant toutes ses cellules."], "answers": ["A", "C", "D"], "explanation": "Les cellules épithéliales sont rapprochées et polarisées. Leur face basale repose sur une lame basale ; leur face apicale regarde la surface ou la lumière d’un organe."}, {"id": 126, "text": "Concernant la nutrition d’un épithélium :", "options": ["Tous les épithéliums contiennent des capillaires entre leurs cellules.", "Un épithélium est dépourvu de vaisseaux sanguins.", "Les nutriments peuvent diffuser depuis le tissu conjonctif sous-jacent.", "Absence de vaisseaux signifie absence totale de nutriments.", "L’épithélium est constitué uniquement de plasma."], "answers": ["B", "C"], "explanation": "Un épithélium est avasculaire. Sa nutrition dépend notamment de la diffusion depuis les vaisseaux du tissu conjonctif adjacent."}, {"id": 127, "text": "Pour classer les épithéliums :", "options": ["Simple signifie une seule couche de cellules.", "Stratifié signifie plusieurs couches de cellules.", "Pavimenteux signifie composé de cellules aplaties.", "Simple signifie sans aucune cellule.", "Stratifié signifie obligatoirement musculaire."], "answers": ["A", "B", "C"], "explanation": "On décrit le nombre de couches (simple ou stratifié) et la forme des cellules (pavimenteuses, cubiques ou cylindriques)."}, {"id": 128, "text": "Quelles associations entre épithélium et fonction sont correctes ?", "options": ["L’épiderme participe à la protection.", "Un épithélium alvéolaire mince favorise les échanges gazeux.", "L’épithélium intestinal contribue à l’absorption.", "L’épiderme est normalement une couche de tissu osseux.", "Tous les épithéliums ont la même épaisseur et la même fonction."], "answers": ["A", "B", "C"], "explanation": "La structure répond à la fonction : protection cutanée, échanges au niveau des alvéoles et absorption intestinale. Dans les alvéoles, les pneumocytes de type I forment la majeure partie de la surface d’échange."}, {"id": 129, "text": "Concernant les glandes :", "options": ["Une glande exocrine déverse sa sécrétion vers une surface ou une lumière, généralement par un canal.", "Une glande endocrine sécrète uniquement à la surface de la peau.", "Une glande endocrine libère ses hormones dans le milieu interstitiel puis la circulation.", "Les glandes sudoripares sont exocrines.", "Toute glande est un muscle squelettique."], "answers": ["A", "C", "D"], "explanation": "Exocrine : sécrétion vers une surface ou une cavité, comme la sueur. Endocrine : hormones libérées vers la circulation après passage dans le milieu interstitiel."}, {"id": 130, "text": "L’endothélium correspond à :", "options": ["Un épithélium qui tapisse l’intérieur des vaisseaux sanguins.", "Un tissu musculaire squelettique.", "Un ensemble de neurones moteurs.", "Un tissu osseux compact.", "La couche externe kératinisée de l’épiderme."], "answers": ["A"], "explanation": "L’endothélium est un épithélium pavimenteux simple qui tapisse notamment la lumière des vaisseaux sanguins. Il constitue une interface entre le sang et la paroi vasculaire."}, {"id": 131, "text": "Un tissu conjonctif comporte typiquement :", "options": ["Des cellules.", "Une matrice extracellulaire.", "Des fibres et une substance fondamentale dans sa matrice.", "Exclusivement des neurones.", "Toujours une absence complète de matrice."], "answers": ["A", "B", "C"], "explanation": "Dans les tissus conjonctifs, les cellules sont associées à une matrice extracellulaire d’abondance variable. Celle-ci comprend une substance fondamentale et, selon le tissu, des fibres."}, {"id": 132, "text": "Concernant les fibres conjonctives :", "options": ["Le collagène contribue à la résistance à la traction.", "L’élastine permet exclusivement la conduction nerveuse.", "Les fibres élastiques contribuent à l’étirement et au retour élastique.", "Les fibroblastes produisent des composants de la matrice extracellulaire.", "Le collagène est une cellule du sang."], "answers": ["A", "C", "D"], "explanation": "Le collagène apporte notamment une résistance mécanique. Les fibres élastiques facilitent le retour après étirement. Les fibroblastes participent à la fabrication et à l’entretien de la matrice."}, {"id": 133, "text": "Concernant le tissu conjonctif lâche et dense :", "options": ["Le tissu lâche accompagne notamment les vaisseaux et soutient des épithéliums.", "Le tissu dense possède une forte proportion de fibres.", "Les tendons sont riches en tissu conjonctif dense.", "Tous les tissus conjonctifs sont liquides.", "Le tissu dense ne comporte jamais de collagène."], "answers": ["A", "B", "C"], "explanation": "Le tissu lâche assure notamment soutien et échanges. Le tissu dense résiste aux contraintes grâce à ses fibres, comme dans les tendons qui relient un muscle à un os."}, {"id": 134, "text": "Quelles propositions concernant le tissu adipeux sont exactes ?", "options": ["Il contient des adipocytes.", "Il participe à la réserve énergétique.", "Il contribue à l’isolation thermique et à la protection mécanique.", "Il constitue un épithélium de revêtement.", "Il n’a aucune activité métabolique."], "answers": ["A", "B", "C"], "explanation": "Le tissu adipeux est un tissu conjonctif spécialisé. Il stocke des lipides, amortit certaines contraintes et participe à la thermorégulation ; il possède aussi une activité endocrine."}, {"id": 135, "text": "Concernant le cartilage :", "options": ["Les chondrocytes sont ses cellules caractéristiques.", "Sa matrice est toujours identique au plasma sanguin.", "Il est normalement dépourvu de vaisseaux sanguins.", "Il constitue à lui seul tous les tendons.", "Le cartilage articulaire contribue au glissement des surfaces articulaires."], "answers": ["A", "C", "E"], "explanation": "Le cartilage associe chondrocytes et matrice spécialisée. Il est avasculaire, ce qui contribue à sa capacité limitée de réparation. Le cartilage articulaire réduit les frottements et répartit les charges."}, {"id": 136, "text": "Concernant le tissu osseux :", "options": ["Il appartient aux tissus conjonctifs spécialisés.", "Sa matrice comporte des composants organiques et des minéraux.", "Il est un tissu vivant qui se remodèle.", "Il est constitué uniquement de cellules mortes.", "Il est identique au tissu nerveux."], "answers": ["A", "B", "C"], "explanation": "L’os associe une matrice organique, notamment du collagène, et une phase minérale. Des cellules assurent son entretien et son remodelage ; ce tissu est vascularisé."}, {"id": 137, "text": "Quelles associations relatives aux cellules osseuses sont correctes ?", "options": ["Ostéoblaste : formation de matrice osseuse.", "Ostéoclaste : résorption osseuse.", "Ostéocyte : cellule osseuse mature intégrée à la matrice.", "Ostéoclaste : sécrétion du mucus intestinal.", "Ostéoblaste : transmission exclusive des influx nerveux."], "answers": ["A", "B", "C"], "explanation": "Les ostéoblastes forment l’os, les ostéoclastes le résorbent et les ostéocytes participent notamment à son entretien. Formation et résorption contribuent au remodelage."}, {"id": 138, "text": "Concernant le sang :", "options": ["C’est un tissu conjonctif spécialisé.", "Les éléments figurés sont présents dans une matrice liquide : le plasma.", "Les hématies transportent notamment l’oxygène grâce à l’hémoglobine.", "Le plasma est une fibre musculaire.", "Les hématies sont des neurones."], "answers": ["A", "B", "C"], "explanation": "Le sang est un tissu conjonctif liquide. Il comporte le plasma et les éléments figurés : hématies, leucocytes et plaquettes, ces dernières étant des fragments cellulaires."}, {"id": 139, "text": "Quelles associations entre élément sanguin et fonction sont correctes ?", "options": ["Leucocytes : participation à la défense immunitaire.", "Plaquettes : participation à l’hémostase.", "Hématies : production des fibres de collagène du derme.", "Plasma : transport de nombreuses substances dissoutes.", "Plaquettes : principale transmission de l’influx nerveux."], "answers": ["A", "B", "D"], "explanation": "Les leucocytes contribuent à la défense, les plaquettes à l’arrêt du saignement et le plasma au transport de substances. Les hématies assurent notamment le transport des gaz respiratoires."}, {"id": 140, "text": "Les trois types de tissu musculaire sont :", "options": ["Strié squelettique.", "Strié cardiaque.", "Lisse.", "Épithélial glandulaire.", "Conjonctif cartilagineux."], "answers": ["A", "B", "C"], "explanation": "Les tissus musculaires se distinguent par leur structure et leur commande : squelettique, cardiaque et lisse. Ils possèdent tous une capacité de contraction."}, {"id": 141, "text": "Concernant le muscle strié squelettique :", "options": ["Il participe aux mouvements et au maintien de la posture.", "Ses fibres sont habituellement longues et plurinucléées.", "Sa commande est principalement somatique et peut être volontaire.", "Il constitue la paroi musculaire de l’intestin.", "Il ne présente jamais de stries au microscope."], "answers": ["A", "B", "C"], "explanation": "Le muscle squelettique est strié, avec des fibres généralement plurinucléées. Il assure notamment les mouvements, la posture et la production de chaleur ; certains mouvements sont aussi réflexes."}, {"id": 142, "text": "Concernant le muscle cardiaque :", "options": ["Il est strié.", "Il forme le myocarde.", "Sa contraction dépend d’une décision volontaire à chaque battement.", "Il fonctionne de manière involontaire.", "Il est identique au cartilage articulaire."], "answers": ["A", "B", "D"], "explanation": "Le myocarde est un muscle strié involontaire. Son automatisme est assuré par des cellules cardiaques spécialisées ; le système nerveux autonome module notamment sa fréquence."}, {"id": 143, "text": "Concernant le muscle lisse :", "options": ["Il est présent dans la paroi de nombreux organes creux.", "Il est présent dans la paroi de nombreux vaisseaux.", "Il fonctionne généralement de manière involontaire.", "Il présente toujours les mêmes stries que le muscle squelettique.", "Il constitue les tendons."], "answers": ["A", "B", "C"], "explanation": "Le muscle lisse contribue au déplacement du contenu des organes creux et au contrôle du calibre des vaisseaux. Il n’a pas de striation visible comme les muscles striés."}, {"id": 144, "text": "Le tissu nerveux comprend :", "options": ["Des neurones.", "Des cellules gliales.", "Uniquement des hématies.", "Des cellules participant à la réception et à la transmission des messages.", "Uniquement des fibres de collagène."], "answers": ["A", "B", "D"], "explanation": "Le tissu nerveux associe neurones et cellules gliales. Les neurones assurent notamment la communication ; la glie participe au soutien, à la protection et au fonctionnement de ce tissu."}, {"id": 145, "text": "Concernant un neurone :", "options": ["Le corps cellulaire contient notamment le noyau.", "Les dendrites participent généralement à la réception des messages.", "L’axone conduit des signaux vers ses terminaisons.", "L’axone est un capillaire sanguin.", "Un neurone est une cellule musculaire lisse."], "answers": ["A", "B", "C"], "explanation": "Corps cellulaire, dendrites et axone sont les repères fondamentaux. Le message peut être transmis à une autre cellule au niveau d’une synapse."}, {"id": 146, "text": "Concernant la myéline :", "options": ["Elle entoure certains axones.", "Tous les axones sont obligatoirement myélinisés.", "Elle facilite une conduction rapide de l’influx dans les fibres myélinisées.", "Elle est produite par certaines cellules gliales.", "Elle correspond au plasma sanguin."], "answers": ["A", "C", "D"], "explanation": "La myéline forme une gaine autour de certains axones et favorise la conduction saltatoire. Les oligodendrocytes la produisent dans le système nerveux central, les cellules de Schwann dans le périphérique."}, {"id": 147, "text": "Concernant la peau et ses tissus :", "options": ["L’épiderme est un épithélium stratifié kératinisé.", "Le derme comporte du tissu conjonctif.", "L’hypoderme comporte notamment du tissu adipeux.", "Le derme est constitué uniquement de neurones.", "L’épiderme contient normalement un réseau de capillaires."], "answers": ["A", "B", "C"], "explanation": "L’épiderme assure une barrière protectrice et reste avasculaire. Le derme contient notamment du tissu conjonctif, des vaisseaux et des nerfs. L’hypoderme, situé sous la peau au sens strict, comporte du tissu adipeux."}, {"id": 148, "text": "À propos de la réparation des tissus :", "options": ["La capacité de réparation varie selon le tissu.", "Une cicatrice peut contenir un tissu conjonctif riche en collagène.", "Tous les tissus récupèrent toujours exactement leur structure initiale.", "La vascularisation et l’état général influencent la cicatrisation.", "Le cartilage articulaire cicatrise aussi facilement que l’épiderme."], "answers": ["A", "B", "D"], "explanation": "La réparation peut associer régénération et formation d’une cicatrice fibreuse. L’apport sanguin et l’état général influencent ce processus ; le cartilage articulaire a une faible capacité de réparation."}], "overview": [["Repère 1", "Épithélial : cellules jointives, revêtement ou sécrétion."], ["Repère 2", "Conjonctif : cellules et matrice ; sang, os, cartilage et adipeux en font partie."], ["Repère 3", "Musculaire : squelettique, cardiaque et lisse."], ["Repère 4", "Nerveux : neurones et glie ; myéline sur certains axones."], ["Repère 5", "Organe = plusieurs tissus ; réparation variable selon le tissu."]], "references": [{"title": "OpenStax · Familles de tissus", "url": "https://openstax.org/books/anatomy-and-physiology-2e/pages/4-1-types-of-tissues"}, {"title": "OpenStax · Épithéliums", "url": "https://openstax.org/books/anatomy-and-physiology-2e/pages/4-2-epithelial-tissue"}, {"title": "OpenStax · Conjonctifs", "url": "https://openstax.org/books/anatomy-and-physiology-2e/pages/4-3-connective-tissue-supports-and-protects"}, {"title": "OpenStax · Muscles", "url": "https://openstax.org/books/anatomy-and-physiology-2e/pages/4-4-muscle-tissue-and-motion"}, {"title": "OpenStax · Tissu nerveux", "url": "https://openstax.org/books/anatomy-and-physiology-2e/pages/4-5-nervous-tissue-mediates-perception-and-response"}]}, {"title": "Anatomie du cœur", "questions": [{"id": 101, "text": "Le cœur se situe :", "options": ["Dans le thorax.", "Dans la cavité abdominale sous le foie.", "Légèrement à gauche du plan médian.", "Dans la cavité pelvienne.", "Entre les deux poumons."], "answers": ["A", "C", "E"], "explanation": "Le cœur est un organe thoracique situé entre les poumons et reposant sur le diaphragme."}, {"id": 102, "text": "Concernant la structure générale du cœur :", "options": ["Il possède quatre cavités principales.", "Il ne possède aucune vascularisation propre.", "C'est un muscle creux.", "Il est formé de quatre oreillettes et d'aucun ventricule.", "Il est totalement dépourvu de cavités."], "answers": ["A", "C"], "explanation": "Le cœur possède sa propre circulation : la circulation coronaire."}, {"id": 103, "text": "Le cœur est entouré :", "options": ["D'un péricarde.", "D'une composante séreuse.", "D'une composante fibreuse.", "D'une seule couche osseuse.", "D'une couche osseuse rigide appelée endocarde."], "answers": ["A", "B", "C"], "explanation": "Le péricarde comprend des composantes fibreuse et séreuse."}, {"id": 104, "text": "Les trois tuniques de la paroi cardiaque sont :", "options": ["Plèvre.", "Endocarde.", "Myocarde.", "Épicarde.", "Péritoine."], "answers": ["B", "C", "D"], "explanation": "De l'extérieur vers l'intérieur : épicarde, myocarde, endocarde."}, {"id": 105, "text": "Concernant le myocarde :", "options": ["C'est un tissu musculaire.", "Est exclusivement constitué de muscle lisse non strié.", "Il est strié.", "Sa contraction est involontaire.", "Il est un épithélium au contact direct du sang."], "answers": ["A", "C", "D"], "explanation": "L'endocarde tapisse l'intérieur ; le myocarde forme la couche musculaire."}, {"id": 106, "text": "L'endocarde :", "options": ["Est au contact du sang.", "Est une artère coronaire.", "Est la couche interne de la paroi.", "Tapisse les cavités cardiaques.", "Est la couche musculaire principale."], "answers": ["A", "C", "D"], "explanation": "L'endocarde revêt l'intérieur du cœur."}, {"id": 107, "text": "Les cavités du cœur comprennent :", "options": ["Deux oreillettes.", "Quatre oreillettes et aucun ventricule.", "Quatre ventricules et aucune oreillette.", "Deux ventricules situés exclusivement dans les poumons.", "Deux ventricules."], "answers": ["A", "E"], "explanation": "Le cœur comprend OD, OG, VD et VG."}, {"id": 108, "text": "Concernant les cloisons et communications :", "options": ["Les ventricules sont séparés par une cloison.", "L'OD communique avec le VD.", "L'OD se vide normalement directement dans le VG.", "Une communication droite-gauche est normale chez l'adulte.", "Les oreillettes sont séparées par un septum."], "answers": ["A", "B", "E"], "explanation": "Normalement, chez l'adulte, les cavités droites et gauches ne communiquent pas directement."}, {"id": 109, "text": "Concernant l'épaisseur des parois :", "options": ["Le VG a une paroi plus épaisse que le VD.", "Le VD a une paroi plus fine que le VG.", "Les oreillettes ont des parois plus fines que les ventricules.", "Toutes les cavités ont exactement la même épaisseur.", "Le VG est dépourvu de muscle."], "answers": ["A", "B", "C"], "explanation": "L'épaisseur varie selon les cavités et le travail qu'elles assurent."}, {"id": 110, "text": "Le sang revient à l'oreillette droite par :", "options": ["Les artères pulmonaires.", "L'aorte.", "Les quatre veines pulmonaires.", "La veine cave supérieure.", "Les quatre veines pulmonaires oxygénées."], "answers": ["D"], "explanation": "Les veines caves ramènent le sang systémique ; le sinus coronaire draine le cœur."}, {"id": 111, "text": "Le ventricule droit :", "options": ["Éjecte directement dans l'aorte.", "Éjecte le sang dans le tronc pulmonaire.", "Envoie le sang vers les poumons.", "Reçoit le sang de l'OD.", "Reçoit normalement le sang des quatre veines pulmonaires."], "answers": ["B", "C", "D"], "explanation": "Le circuit droit propulse le sang vers la circulation pulmonaire."}, {"id": 112, "text": "Les veines pulmonaires :", "options": ["Arrivent à l'OG.", "Arrivent normalement au VD.", "Transportent normalement le sang de l'aorte vers les reins.", "Transportent normalement du sang oxygéné.", "Transportent le sang du VG vers l'organisme."], "answers": ["A", "D"], "explanation": "Elles ramènent à l'OG le sang oxygéné dans les poumons."}, {"id": 113, "text": "Le ventricule gauche :", "options": ["Éjecte normalement son sang dans la veine cave supérieure.", "Alimente la circulation générale.", "Se vide dans la veine cave inférieure.", "Reçoit le sang de l'OG.", "Éjecte dans l'aorte."], "answers": ["B", "D", "E"], "explanation": "Le VG assure l'éjection dans la circulation systémique."}, {"id": 114, "text": "Les valves cardiaques :", "options": ["Se ferment selon les différences de pression.", "S'ouvrent indépendamment de toute différence de pression.", "Favorisent un écoulement à sens unique.", "S'ouvrent selon les différences de pression.", "Restent toujours ouvertes."], "answers": ["A", "C", "D"], "explanation": "Leur ouverture et leur fermeture dépendent des pressions de part et d'autre."}, {"id": 115, "text": "La valve tricuspide :", "options": ["Sépare l'OD et le VD.", "Sépare le VG et l'aorte.", "Est une valve auriculo-ventriculaire.", "Est située entre le VG et l'aorte.", "Se situe à droite."], "answers": ["A", "C", "E"], "explanation": "La tricuspide est la valve auriculo-ventriculaire droite."}, {"id": 116, "text": "La valve mitrale, ou bicuspide :", "options": ["Sépare l'OG et le VG.", "Est la valve de sortie du VD.", "Est à gauche.", "Est auriculo-ventriculaire.", "Sépare le VD et le tronc pulmonaire."], "answers": ["A", "C", "D"], "explanation": "La mitrale est la valve auriculo-ventriculaire gauche."}, {"id": 117, "text": "Les valves de sortie des ventricules sont :", "options": ["La mitrale à la sortie du VD vers les poumons.", "La valve aortique empêche le retour de l'aorte vers l'OG.", "La tricuspide à la sortie du VG vers l'aorte.", "La valve pulmonaire à la sortie du VD.", "La valve aortique à la sortie du VG."], "answers": ["D", "E"], "explanation": "Les valves pulmonaire et aortique limitent le reflux vers les ventricules."}, {"id": 118, "text": "Les cordages tendineux :", "options": ["Participent au maintien de ces valves.", "Sont associés aux valves auriculo-ventriculaires.", "Sont associés uniquement aux valves aortique et pulmonaire.", "Sont les quatre veines pulmonaires.", "Sont associés à la tricuspide."], "answers": ["A", "B", "E"], "explanation": "Le support décrit les valves auriculo-ventriculaires comme maintenues par des cordages."}, {"id": 119, "text": "Concernant la vascularisation du cœur :", "options": ["Le myocarde n'a pas besoin de circulation propre.", "Elles irriguent le cœur lui-même.", "Elles se subdivisent en branches.", "Les coronaires droite et gauche naissent de l'aorte.", "Les artères coronaires naissent normalement des veines caves."], "answers": ["B", "C", "D"], "explanation": "Le cœur possède une circulation coronaire artérielle et un drainage veineux."}, {"id": 120, "text": "Quel trajet du sang est correct ?", "options": ["OG → VD → veine cave : trajet normal.", "Veines caves → OD → VD → tronc pulmonaire.", "Le sang s'écoule toujours de la basse vers la haute pression.", "Aorte → OG → veines caves : trajet normal.", "Poumons → aorte → OD : trajet normal."], "answers": ["B"], "explanation": "Le circuit droit conduit aux poumons ; le circuit gauche conduit à l'organisme."}]}, {"title": "La cellule, ses organites et la communication intercellulaire", "description": "B.1.a · S1 · 20 QCM corrigés", "courseId": "b1-cellule", "questions": [{"text": "Dans une cellule humaine typique :", "options": ["Le cytoplasme contient des organites.", "La membrane est une paroi de cartilage.", "Toutes les cellules humaines matures possèdent un noyau.", "Le noyau contient la majeure partie de l’ADN.", "Le cytosol est la partie liquide du cytoplasme."], "answers": ["A", "D", "E"], "explanation": "Le noyau, le cytosol et les organites sont des repères d’une cellule typique. Les hématies matures n’ont plus de noyau : la formulation « toutes » serait fausse.", "id": 2100}, {"text": "Quelles associations d’organites sont correctes ?", "options": ["Golgi : modification et tri de certaines molécules.", "Réticulum lisse : revêtement osseux.", "Mitochondrie : production d’une part importante de l’ATP.", "Lysosome : formation principale des chromosomes homologues.", "Ribosome : synthèse des protéines."], "answers": ["A", "C", "E"], "explanation": "Ribosomes, Golgi et mitochondries ont des fonctions distinctes. Les lysosomes participent à des dégradations ; le réticulum lisse notamment à la synthèse lipidique.", "id": 2101}, {"text": "Une protéine destinée à être sécrétée suit classiquement :", "options": ["Une transformation obligatoire en chromosome.", "Un transport vésiculaire puis une exocytose.", "Un ribosome associé au réticulum rugueux.", "Une sortie par méiose.", "Un passage par le Golgi."], "answers": ["B", "C", "E"], "explanation": "La voie sécrétoire classique associe réticulum rugueux, Golgi et vésicules. L’exocytose libère le contenu vers l’extérieur ; la méiose est une division cellulaire.", "id": 2102}, {"text": "La bicouche de phospholipides possède :", "options": ["Des queues hydrophobes obligatoirement exposées au milieu aqueux extérieur.", "Uniquement des protéines, sans lipides.", "Des queues hydrophobes orientées vers l’intérieur de la bicouche.", "Une organisation contribuant à une barrière sélective.", "Des têtes hydrophiles vers les milieux aqueux."], "answers": ["C", "D", "E"], "explanation": "Les têtes interagissent avec l’eau et les queues se regroupent au cœur de la bicouche. Cette organisation participe à la perméabilité sélective.", "id": 2103}, {"text": "Les protéines membranaires peuvent agir comme :", "options": ["Noyaux cellulaires complets.", "Transporteurs.", "Canaux.", "Chromosomes homologues.", "Récepteurs."], "answers": ["B", "C", "E"], "explanation": "Une membrane porte des protéines aux fonctions diverses. Canaux, transporteurs et récepteurs ne sont pas interchangeables mais participent aux échanges et aux réponses.", "id": 2104}, {"text": "La diffusion simple de O₂ à travers la membrane :", "options": ["Est un transport passif.", "Suit un gradient de concentration pour le déplacement net.", "Peut se faire sans transporteur.", "Exige une hydrolyse d’ATP par une pompe pour chaque O₂.", "Est une forme de méiose."], "answers": ["A", "B", "C"], "explanation": "O₂ peut diffuser dans la bicouche selon son gradient, sans transporteur ni énergie directement dépensée pour ce passage.", "id": 2105}, {"text": "La diffusion facilitée :", "options": ["Peut suivre un gradient électrochimique pour un ion.", "Exige toujours une vésicule.", "Reste un mécanisme passif.", "Est toujours active parce qu’une protéine intervient.", "Utilise un canal ou un transporteur."], "answers": ["A", "C", "E"], "explanation": "Une protéine peut faciliter un passage passif. Le critère déterminant est le déplacement selon le gradient, pas la simple présence d’une protéine.", "id": 2106}, {"text": "Concernant les transports actifs :", "options": ["Le transport secondaire peut exploiter un gradient couplé.", "Ils correspondent toujours à une diffusion simple.", "Ils sont tous sans source d’énergie.", "Le transport primaire peut utiliser directement l’ATP.", "Ils peuvent permettre un déplacement contre un gradient."], "answers": ["A", "D", "E"], "explanation": "Le primaire utilise directement une source énergétique ; le secondaire utilise l’énergie d’un gradient. Tous deux se distinguent d’une diffusion simple passive.", "id": 2107}, {"text": "La pompe Na⁺/K⁺, par cycle utilisant un ATP :", "options": ["Fait entrer 2 K⁺.", "Participe au maintien de gradients ioniques.", "Supprime toute différence électrique possible entre les milieux.", "Fait sortir 3 Na⁺.", "Fait sortir 2 K⁺ et entrer 3 Na⁺."], "answers": ["A", "B", "D"], "explanation": "La pompe fait sortir 3 sodium et entrer 2 potassium. Elle entretient des gradients et ne supprime pas toutes les différences entre les compartiments.", "id": 2108}, {"text": "Dans un modèle de cellule placée en milieu hypertonique :", "options": ["La cellule gonfle toujours par entrée d’eau.", "Les protéines deviennent automatiquement des ions.", "L’eau peut quitter la cellule.", "La cellule peut diminuer de volume.", "La tonicité dépend des solutés efficaces."], "answers": ["C", "D", "E"], "explanation": "Un milieu hypertonique peut entraîner une perte d’eau et une diminution du volume cellulaire. La tonicité dépend de la membrane et des solutés ne diffusant pas librement.", "id": 2109}, {"text": "Quelles propositions distinguent les transports vésiculaires ?", "options": ["L’exocytose libère un contenu vers l’extérieur.", "L’endocytose internalise du matériel.", "Ils se distinguent du passage direct à travers la membrane.", "L’endocytose est une séparation de chromatides.", "L’exocytose est toujours une diffusion de gaz."], "answers": ["A", "B", "C"], "explanation": "Ces mécanismes utilisent des vésicules. Ils ne sont ni des divisions chromosomiques ni une diffusion simple à travers la bicouche.", "id": 2110}, {"text": "Une cellule répond à un signal lorsque :", "options": ["Le récepteur peut être membranaire ou intracellulaire selon le signal.", "Toute hormone agit forcément sur toutes les cellules.", "Elle possède un récepteur et une voie de réponse adaptés.", "Le signal entraîne une transduction puis une réponse.", "Le signal doit toujours entrer directement dans le noyau."], "answers": ["A", "C", "D"], "explanation": "La réponse dépend du récepteur et des mécanismes internes. Certains récepteurs sont membranaires, d’autres intracellulaires ; toutes les cellules ne répondent pas à tous les signaux.", "id": 2111}, {"text": "Quelles associations de communication sont correctes ?", "options": ["Endocrine : circulation vers une cible distante.", "Paracrine : cible voisine.", "Endocrine : aucune molécule signal.", "Synaptique : obligatoirement transport d’urine.", "Autocrine : cellule émettrice elle-même."], "answers": ["A", "B", "E"], "explanation": "La portée et le trajet du signal distinguent endocrine, paracrine et autocrine. La communication synaptique correspond à un message au niveau d’une synapse.", "id": 2112}, {"text": "À propos des chromosomes :", "options": ["La réplication double nécessairement le nombre de chromosomes avant séparation.", "Une chromatide est une cellule entière.", "Deux homologues peuvent porter des allèles différents.", "Après réplication, un chromosome comporte deux chromatides sœurs.", "Les chromosomes homologues portent les mêmes catégories de gènes."], "answers": ["C", "D", "E"], "explanation": "La réplication double la quantité d’ADN et produit deux chromatides par chromosome sans doubler immédiatement le nombre de chromosomes. Homologues ne signifie pas allèles identiques.", "id": 2113}, {"text": "Une cellule somatique humaine nucléée typique possède :", "options": ["46 chromosomes.", "23 chromosomes au total comme un gamète.", "Un état diploïde.", "Toujours 92 chromosomes avant la phase S.", "23 paires de chromosomes."], "answers": ["A", "C", "E"], "explanation": "Une cellule somatique typique est diploïde avec 46 chromosomes, soit 23 paires. Après réplication, elle possède encore 46 chromosomes, mais à deux chromatides chacun.", "id": 2114}, {"text": "La réplication de l’ADN du cycle cellulaire intervient :", "options": ["Avant une mitose dans un cycle classique.", "Uniquement après la fécondation pour toute la vie.", "Avant la première division méiotique dans le schéma étudié.", "Obligatoirement entre méiose I et II.", "En phase S."], "answers": ["A", "C", "E"], "explanation": "La phase S précède la division. La méiose associe une seule réplication avant deux divisions, sans nouvelle phase S entre I et II.", "id": 2115}, {"text": "La méiose I sépare principalement :", "options": ["Deux couches de phospholipides.", "Les organes d’un appareil.", "Deux lots de chromosomes en réduisant la ploïdie.", "Les chromosomes homologues.", "Les chromatides sœurs de chaque chromosome comme étape principale."], "answers": ["C", "D"], "explanation": "La première division est réductionnelle : elle sépare les homologues. Les chromatides sœurs restent associées jusqu’à la deuxième division.", "id": 2116}, {"text": "Après méiose I chez l’humain, chaque cellule possède normalement :", "options": ["Un état haploïde.", "Un état identique au départ diploïde pour le nombre de jeux.", "23 chromosomes à deux chromatides.", "23 chromosomes.", "46 chromosomes à une chromatide."], "answers": ["A", "C", "D"], "explanation": "La cellule est haploïde après la séparation des homologues. Elle possède 23 chromosomes, chacun encore composé de deux chromatides.", "id": 2117}, {"text": "Concernant la méiose II :", "options": ["Elle est précédée d’une nouvelle réplication complète de l’ADN.", "Elle rétablit à elle seule un lot diploïde.", "Elle suit la première division méiotique.", "Ses produits ont normalement 23 chromosomes à une chromatide chez l’humain.", "Elle sépare les chromatides sœurs."], "answers": ["C", "D", "E"], "explanation": "Méiose II sépare les chromatides sans réplication entre les deux divisions. La diploïdie est rétablie par la fécondation, pas par cette division.", "id": 2118}, {"text": "La diversité génétique et la formation des gamètes impliquent :", "options": ["Une répartition des homologues pendant méiose I.", "Des échanges entre chromatides non sœurs d’homologues en prophase I.", "Une fécondation réunissant deux lots haploïdes.", "Une absence totale de brassage lors de la méiose.", "Quatre ovules fonctionnels produits systématiquement par toute méiose féminine."], "answers": ["A", "B", "C"], "explanation": "Crossing-over et répartition des homologues contribuent au brassage. L’ovogenèse est asymétrique : elle ne produit pas quatre ovules fonctionnels à partir d’une cellule.", "id": 2119}], "overview": [["Repère 1", "Membrane = bicouche lipidique et protéines, à perméabilité sélective."], ["Repère 2", "Diffusion facilitée reste passive ; transport actif peut aller contre un gradient."], ["Repère 3", "Noyau : information ; ribosome : protéines ; Golgi : tri ; mitochondrie : ATP."], ["Repère 4", "Signal → récepteur → transduction → réponse ; seule une cible adaptée répond."], ["Repère 5", "Méiose I : homologues ; méiose II : chromatides ; une réplication, deux divisions."]], "references": [{"title": "OpenStax · Membrane et transports", "url": "https://openstax.org/books/anatomy-and-physiology-2e/pages/3-1-the-cell-membrane"}, {"title": "OpenStax · Cytoplasme et organites", "url": "https://openstax.org/books/anatomy-and-physiology-2e/pages/3-2-the-cytoplasm-and-cellular-organelles"}, {"title": "OpenStax · Signalisation", "url": "https://openstax.org/books/biology-2e/pages/9-1-signaling-molecules-and-cellular-receptors"}, {"title": "OpenStax · Méiose", "url": "https://openstax.org/books/biology-2e/pages/11-1-the-process-of-meiosis"}]}, {"title": "Anatomie régionale, vocabulaire et appareil locomoteur", "description": "B.1.a · S1 · 20 QCM corrigés", "courseId": "b1-anatomie", "questions": [{"text": "La position anatomique de référence comprend :", "options": ["Une personne obligatoirement en décubitus ventral.", "Une personne debout.", "Les paumes vers l’avant.", "Le regard vers l’avant.", "Les côtés définis du point de vue de l’observateur."], "answers": ["B", "C", "D"], "explanation": "La convention est debout, regard en avant et paumes en avant. Les côtés sont ceux de la personne, même si elle change ensuite de position.", "id": 2300}, {"text": "Un patient est face à toi. Pour indiquer sa douleur à droite :", "options": ["La position du soignant ne change pas le côté anatomique.", "Tu utilises toujours ta droite.", "La droite devient la gauche en décubitus.", "Tu utilises sa droite.", "Le côté reste celui du patient s’il s’allonge."], "answers": ["A", "D", "E"], "explanation": "Droite et gauche sont celles du patient et ne changent pas selon le point de vue ou sa position. Cette précision évite les erreurs de transmission.", "id": 2301}, {"text": "Quelles associations de plans sont correctes ?", "options": ["Transversal : toujours avant et arrière.", "Transversal : supérieur et inférieur.", "Sagittal : parties droite et gauche.", "Frontal : toujours droite et gauche.", "Frontal : antérieur et postérieur."], "answers": ["B", "C", "E"], "explanation": "Sagittal, frontal et transversal décrivent trois orientations différentes. Le plan médian est un plan sagittal passant par le milieu.", "id": 2302}, {"text": "En anatomie, proximal signifie :", "options": ["Synonyme de distal.", "Toujours sur le côté gauche.", "Plus proche de l’origine ou de l’attache.", "Le coude est proximal au poignet sur le membre supérieur.", "Toujours plus proche de la peau."], "answers": ["C", "D"], "explanation": "Proximal et distal se rapportent à l’origine ou à l’attache d’une structure. Ils ne décrivent ni le côté ni la profondeur.", "id": 2303}, {"text": "En position anatomique :", "options": ["Superficiel signifie toujours proximal.", "Médial signifie proche du plan médian.", "Le sternum est antérieur au cœur.", "Le pouce est latéral au petit doigt.", "Le coude est distal au poignet."], "answers": ["B", "C", "D"], "explanation": "Antérieur, latéral et médial décrivent des relations anatomiques. Le coude est proximal au poignet ; superficialité et proximité d’attache sont des axes différents.", "id": 2304}, {"text": "La cavité crânienne et le canal vertébral contiennent respectivement :", "options": ["Moelle osseuse et estomac.", "Poumons et reins.", "Vessie et foie.", "Encéphale et moelle épinière.", "Cœur et pancréas."], "answers": ["D"], "explanation": "L’encéphale est protégé par le crâne ; la moelle épinière par le canal vertébral. La moelle osseuse, impliquée dans la production sanguine, est différente.", "id": 2305}, {"text": "Concernant le diaphragme :", "options": ["C’est un muscle.", "Il contribue à la ventilation.", "C’est une valve cardiaque.", "Il sépare thorax et abdomen.", "Il ne peut pas se contracter."], "answers": ["A", "B", "D"], "explanation": "Le diaphragme est un muscle respiratoire séparant thorax et abdomen. Sa contraction contribue à l’inspiration.", "id": 2306}, {"text": "Les feuillets d’une séreuse sont décrits comme :", "options": ["Pariétal vers la paroi.", "Toujours osseux et cartilagineux.", "Deux moitiés d’un chromosome.", "Des repères applicables notamment à la plèvre.", "Viscéral au contact de l’organe."], "answers": ["A", "D", "E"], "explanation": "Pariétal et viscéral distinguent la relation du feuillet avec la paroi et l’organe. Plèvre et péritoine sont des séreuses de localisations différentes.", "id": 2307}, {"text": "Dans le découpage abdominal en neuf régions :", "options": ["L’hypogastre est une région centrale inférieure.", "La région ombilicale est située dans le crâne.", "L’épigastre est une région centrale supérieure.", "Les fosses iliaques sont toutes deux à droite du patient.", "Les hypochondres occupent les régions latérales supérieures."], "answers": ["A", "C", "E"], "explanation": "La disposition supérieure comprend les hypochondres et l’épigastre ; la partie inférieure les fosses iliaques et l’hypogastre. Les repères sont ceux du patient.", "id": 2308}, {"text": "Une transmission sur une douleur doit préciser notamment :", "options": ["Un diagnostic certain déduit du côté seul.", "Ses caractéristiques et son intensité.", "Seulement « ça fait mal ».", "Son début et son évolution.", "La localisation et le côté."], "answers": ["B", "D", "E"], "explanation": "Une description précise est utile à l’évaluation. Une localisation seule ne permet pas de conclure à une cause ou à un diagnostic.", "id": 2309}, {"text": "Quelles associations de vocabulaire sont correctes ?", "options": ["Néphro- : cœur.", "-ite : preuve obligatoire d’une infection.", "Brady- : lent.", "-algie : douleur.", "Tachy- : rapide."], "answers": ["C", "D", "E"], "explanation": "Brady et tachy qualifient notamment une vitesse ou fréquence ; algie évoque une douleur. -ite indique une inflammation, qui peut être non infectieuse ; néphro renvoie au rein.", "id": 2310}, {"text": "Une personne allongée sur le dos est en :", "options": ["Abduction.", "Décubitus ventral.", "Position anatomique debout.", "Décubitus dorsal.", "Décubitus latéral."], "answers": ["D"], "explanation": "Dorsal : sur le dos ; ventral : sur le ventre ; latéral : sur le côté. Abduction est un mouvement, pas une position de décubitus.", "id": 2311}, {"text": "Le squelette axial comprend notamment :", "options": ["Le crâne.", "Uniquement le fémur.", "Uniquement les os des mains.", "La cage thoracique.", "La colonne vertébrale."], "answers": ["A", "D", "E"], "explanation": "Le squelette axial organise l’axe du corps. Les ceintures et membres appartiennent au squelette appendiculaire.", "id": 2312}, {"text": "Quelles associations os-région sont correctes ?", "options": ["Radius et ulna : avant-bras.", "Tibia : avant-bras.", "Patella : crâne.", "Humérus : bras.", "Fémur : cuisse."], "answers": ["A", "D", "E"], "explanation": "Humérus au bras, radius et ulna à l’avant-bras, fémur à la cuisse. Tibia est un os de la jambe et patella un os situé au genou.", "id": 2313}, {"text": "La moelle osseuse rouge :", "options": ["Se situe dans des espaces osseux.", "Est une couche de l’épiderme.", "Participe à la formation des cellules sanguines.", "Conduit tous les influx de la moelle épinière.", "Est identique à la moelle épinière."], "answers": ["A", "C"], "explanation": "La moelle osseuse rouge est hématopoïétique et se trouve dans les os. La moelle épinière appartient au système nerveux central.", "id": 2314}, {"text": "Une articulation synoviale comporte notamment :", "options": ["Une cavité avec liquide synovial.", "Une capsule articulaire.", "Un épithélium cutané entre tous les os.", "Une absence obligatoire de mouvement.", "Des surfaces articulaires recouvertes de cartilage."], "answers": ["A", "B", "E"], "explanation": "Une articulation synoviale a une cavité et des structures facilitant le mouvement. Le cartilage articulaire et le liquide synovial contribuent au glissement et aux contraintes.", "id": 2315}, {"text": "Concernant tendon et ligament :", "options": ["Un ligament relie généralement des os.", "Tendon signifie toujours neurone.", "Tendon et ligament désignent exactement la même fonction.", "Un tendon transmet la force d’un muscle vers son insertion.", "Un ligament peut stabiliser une articulation."], "answers": ["A", "D", "E"], "explanation": "Ces structures conjonctives ont des fonctions dominantes différentes : transmission musculaire pour le tendon, liaison et stabilité pour le ligament.", "id": 2316}, {"text": "Quelles associations de mouvements sont correctes ?", "options": ["Extension : augmentation habituelle d’un angle articulaire.", "Pronation : définition exclusive d’une flexion du genou.", "Flexion : diminution habituelle d’un angle articulaire.", "Adduction : éloignement du plan médian.", "Abduction : éloignement du plan médian."], "answers": ["A", "C", "E"], "explanation": "Flexion/extension concernent un angle ; abduction/adduction une relation au plan médian. La pronation concerne notamment l’orientation de l’avant-bras.", "id": 2317}, {"text": "L’anatomie et la physiologie se distinguent ainsi :", "options": ["L’anatomie est exclusivement l’étude des médicaments.", "La physiologie ne concerne jamais les organes.", "L’anatomie décrit des structures.", "La physiologie étudie des fonctions.", "Les deux approches peuvent être reliées."], "answers": ["C", "D", "E"], "explanation": "Structure et fonction se complètent. Comprendre l’organisation d’un organe aide à comprendre son fonctionnement et les observations de soins.", "id": 2318}, {"text": "Pour mobiliser un patient :", "options": ["La douleur et l’équilibre sont des informations utiles.", "L’apprentissage pratique encadré reste nécessaire.", "Le vocabulaire seul suffit pour réaliser tout transfert.", "Les restrictions et capacités doivent être prises en compte.", "L’observation sensitive est inutile."], "answers": ["A", "B", "D"], "explanation": "La mobilisation ne dépend pas seulement des noms anatomiques. Elle exige évaluation et gestes adaptés, en respectant l’encadrement et les consignes.", "id": 2319}], "overview": [["Repère 1", "Les côtés sont ceux du patient."], ["Repère 2", "Sagittal : droite/gauche ; frontal : avant/arrière ; transversal : haut/bas."], ["Repère 3", "Proximal et distal sont relatifs à une origine ou une attache."], ["Repère 4", "Tendon : transmission musculaire ; ligament : liaison et stabilité."], ["Repère 5", "Flexion/extension et abduction/adduction ne sont pas synonymes."]], "references": [{"title": "OpenStax · Terminologie anatomique", "url": "https://openstax.org/books/anatomy-and-physiology-2e/pages/1-6-anatomical-terminology"}, {"title": "OpenStax · Organisation", "url": "https://openstax.org/books/anatomy-and-physiology-2e/pages/1-2-structural-organization-of-the-human-body"}, {"title": "OpenStax · Squelette axial", "url": "https://openstax.org/books/anatomy-and-physiology-2e/pages/7-1-divisions-of-the-skeletal-system"}, {"title": "OpenStax · Articulations", "url": "https://openstax.org/books/anatomy-and-physiology-2e/pages/9-4-synovial-joints"}]}, {"title": "Représentation générale des systèmes humains", "description": "B.1.a · S1 · 20 QCM corrigés", "courseId": "b1-systemes", "questions": [{"text": "Un appareil ou système :", "options": ["Est identique à une cellule isolée.", "Permet de comprendre des coopérations dans le corps.", "Fonctionne toujours sans lien avec les autres.", "Peut partager des organes avec d’autres fonctions.", "Associe des organes contribuant à des fonctions."], "answers": ["B", "D", "E"], "explanation": "Les systèmes sont des ensembles fonctionnels qui coopèrent. Le pancréas et les reins illustrent des organes participant à plusieurs fonctions.", "id": 2400}, {"text": "L’homéostasie correspond à :", "options": ["La cessation de tout métabolisme.", "L’absence totale de variation d’une constante.", "Une situation compatible avec la vie dans des plages adaptées.", "Des mécanismes de régulation.", "Un équilibre interne dynamique."], "answers": ["C", "D", "E"], "explanation": "L’homéostasie est régulée et dynamique. Elle ne signifie ni immobilité absolue des valeurs ni arrêt des réactions.", "id": 2401}, {"text": "Un rétrocontrôle négatif :", "options": ["Est un mécanisme de régulation.", "Signifie que la réponse est forcément dangereuse.", "Amplifie toujours indéfiniment la perturbation.", "Peut contribuer à la régulation thermique.", "Tend à réduire une perturbation."], "answers": ["A", "D", "E"], "explanation": "Négatif décrit l’opposition à la perturbation, pas un jugement de valeur. La régulation de température peut en donner un exemple.", "id": 2402}, {"text": "Le système nerveux central comprend :", "options": ["La moelle épinière.", "Tous les ganglions périphériques.", "L’encéphale.", "Le foie.", "La vessie."], "answers": ["A", "C"], "explanation": "Encéphale et moelle épinière constituent le système nerveux central ; les nerfs et ganglions périphériques appartiennent au périphérique.", "id": 2403}, {"text": "Une voie sensitive et une voie motrice :", "options": ["Participent à la relation et à la régulation.", "N’ont aucun lien avec les muscles ou organes.", "Apportent et transmettent respectivement des informations et des commandes dans le schéma fonctionnel.", "Correspondent toutes deux exclusivement à la bile.", "S’intègrent dans le système nerveux."], "answers": ["A", "C", "E"], "explanation": "Le schéma général distingue entrée sensitive et sortie motrice. Il aide à comprendre observation et réponse, sans résumer toutes les voies nerveuses à une seule connexion.", "id": 2404}, {"text": "Le système endocrinien :", "options": ["Utilise des hormones.", "Agit toujours sans récepteur.", "Agit sur des cellules possédant des mécanismes de réception adaptés.", "Est uniquement constitué de tendons.", "Comprend notamment la thyroïde et les surrénales."], "answers": ["A", "C", "E"], "explanation": "Les hormones et leurs cibles sont le repère principal. Les organes endocriniens sont variés et coopèrent avec d’autres systèmes.", "id": 2405}, {"text": "Concernant les vaisseaux :", "options": ["Les capillaires sont des lieux d’échanges.", "Toutes les artères transportent obligatoirement un sang riche en O₂.", "Une veine ramène le sang vers le cœur.", "Une artère conduit le sang depuis le cœur.", "Une veine se définit par l’absence d’oxygène."], "answers": ["A", "C", "D"], "explanation": "Le sens de circulation définit artère et veine. Les artères pulmonaires et veines pulmonaires montrent pourquoi l’oxygénation n’est pas le critère du nom.", "id": 2406}, {"text": "La circulation et la respiration coopèrent car :", "options": ["Le cœur et les vaisseaux transportent le sang.", "Les poumons permettent les échanges gazeux avec le sang.", "Les tissus utilisent notamment l’O₂.", "Les tissus sont directement remplis d’air inspiré par toutes les artères.", "Les reins remplacent les poumons pour toutes les entrées d’air."], "answers": ["A", "B", "C"], "explanation": "L’oxygène passe des alvéoles au sang puis aux tissus. La circulation assure le transport entre échange pulmonaire et utilisation cellulaire.", "id": 2407}, {"text": "La ventilation désigne :", "options": ["La seule synthèse du glucose.", "Le mouvement de l’air inspiré et expiré.", "Un phénomène auquel contribue le diaphragme.", "La totalité de la production d’urine.", "La circulation de bile."], "answers": ["B", "C"], "explanation": "La ventilation est le mouvement de l’air. Elle se distingue des échanges alvéolocapillaires et de l’utilisation de l’oxygène par les cellules.", "id": 2408}, {"text": "Au niveau alvéolocapillaire, habituellement :", "options": ["Le CO₂ est transformé en globules rouges.", "Le CO₂ diffuse vers les alvéoles.", "Les échanges suivent des gradients.", "L’O₂ diffuse vers le sang.", "L’air circule directement dans la vessie."], "answers": ["B", "C", "D"], "explanation": "Les gaz suivent leurs gradients à travers la barrière alvéolocapillaire. Le transport sanguin complète ensuite cet échange.", "id": 2409}, {"text": "Concernant le système lymphatique :", "options": ["Il produit toute l’urine.", "Les ganglions sont tous des pompes cardiaques.", "Il contribue au retour du liquide interstitiel vers la circulation.", "Il participe aux défenses immunitaires.", "Les ganglions sont des lieux de surveillance immunitaire."], "answers": ["C", "D", "E"], "explanation": "Retour lymphatique et défenses sont deux fonctions importantes. Les ganglions ne remplacent pas le cœur et ne produisent pas l’urine.", "id": 2410}, {"text": "Le tube digestif comprend notamment :", "options": ["L’œsophage.", "L’intestin grêle.", "L’urètre.", "L’estomac.", "La trachée."], "answers": ["A", "B", "D"], "explanation": "Œsophage, estomac et intestin appartiennent au tube digestif. Urètre est urinaire, trachée respiratoire.", "id": 2411}, {"text": "Quelles associations digestives sont correctes ?", "options": ["Intestin grêle : site majeur d’absorption des nutriments.", "Vésicule biliaire : production de tous les globules blancs.", "Côlon : pompe principale de la circulation.", "Foie : production de bile.", "Vésicule biliaire : stockage et concentration de bile."], "answers": ["A", "D", "E"], "explanation": "La bile est produite par le foie et stockée dans la vésicule. L’intestin grêle assure une grande part de l’absorption des nutriments.", "id": 2412}, {"text": "Le pancréas possède :", "options": ["Une fonction exocrine digestive.", "Une fonction endocrine.", "Une production hormonale comprenant insuline et glucagon.", "Une fonction unique de protection du crâne.", "Une fonction exclusive de stockage de l’urine."], "answers": ["A", "B", "C"], "explanation": "Le pancréas est un exemple d’organe à fonctions multiples : sécrétions digestives exocrines et hormones endocrines.", "id": 2413}, {"text": "Concernant les reins :", "options": ["Ils contribuent à l’équilibre hydrique et ionique.", "Ils servent uniquement de poche de stockage.", "Ils ont aussi des fonctions endocrines.", "Ils produisent l’urine.", "Ils n’interviennent jamais dans l’équilibre acido-basique."], "answers": ["A", "C", "D"], "explanation": "Les reins produisent l’urine et ont des fonctions de régulation et endocrines. La vessie stocke ; les reins ne sont pas de simples réservoirs.", "id": 2414}, {"text": "Quel trajet de l’urine est correct ?", "options": ["Reins → uretères → vessie → urètre.", "Urètre → poumons → vésicule biliaire.", "Uretères → trachée → reins.", "Reins → urètre → vessie → uretères.", "Vessie → foie → estomac."], "answers": ["A"], "explanation": "Uretères et urètre sont distincts : les premiers conduisent depuis les reins, le second évacue depuis la vessie.", "id": 2415}, {"text": "La diurèse doit être décrite par :", "options": ["Le seul nom du patient sans valeur.", "Une quantité d’urine.", "Une durée de mesure.", "La quantité de bile sans intervalle.", "Des unités adaptées."], "answers": ["B", "C", "E"], "explanation": "Une quantité d’urine devient interprétable avec son intervalle et son unité, par exemple un volume sur une durée. Le contexte clinique reste nécessaire.", "id": 2416}, {"text": "La peau contribue notamment :", "options": ["À la production de toute l’urine.", "À la sensibilité.", "À la protection.", "À la thermorégulation.", "À la formation de toute la bile."], "answers": ["B", "C", "D"], "explanation": "Le système tégumentaire forme une barrière et participe à sensibilité et régulation thermique. Les fonctions urinaires et biliaires appartiennent à d’autres organes.", "id": 2417}, {"text": "Concernant la reproduction humaine :", "options": ["Les gamètes possèdent normalement chacun 46 chromosomes.", "Les testicules produisent des spermatozoïdes.", "La fécondation se déroule habituellement dans une trompe utérine.", "Les ovaires participent à la maturation des ovocytes.", "L’implantation normale se fait dans la vessie."], "answers": ["B", "C", "D"], "explanation": "Gamètes haploïdes, fécondation habituellement tubaire puis implantation utérine sont des repères distincts. Les gamètes possèdent normalement 23 chromosomes.", "id": 2418}, {"text": "Lors d’un effort physique :", "options": ["La régulation nerveuse et hormonale participe à l’adaptation.", "Les besoins des muscles peuvent augmenter.", "La production de chaleur devient forcément nulle.", "Tous les systèmes deviennent indépendants les uns des autres.", "La ventilation et la circulation peuvent s’adapter."], "answers": ["A", "B", "E"], "explanation": "L’effort montre l’interdépendance des systèmes : approvisionnement, commandes et gestion thermique coopèrent pour répondre aux besoins.", "id": 2419}], "overview": [["Repère 1", "Homéostasie = équilibre dynamique, pas stabilité absolue."], ["Repère 2", "Système nerveux : informations et commandes ; endocrinien : hormones et cibles."], ["Repère 3", "Respiration et circulation coopèrent pour fournir l’oxygène aux cellules."], ["Repère 4", "Reins produisent l’urine ; vessie la stocke."], ["Repère 5", "Un organe peut avoir plusieurs fonctions : foie, reins et pancréas."]], "references": [{"title": "OpenStax · Organisation des systèmes", "url": "https://openstax.org/books/anatomy-and-physiology-2e/pages/1-2-structural-organization-of-the-human-body"}, {"title": "OpenStax · Homéostasie", "url": "https://openstax.org/books/anatomy-and-physiology-2e/pages/1-5-homeostasis"}, {"title": "OpenStax · Vue d’ensemble de la digestion", "url": "https://openstax.org/books/anatomy-and-physiology-2e/pages/23-1-overview-of-the-digestive-system"}, {"title": "OpenStax · Voies urinaires", "url": "https://openstax.org/books/anatomy-and-physiology-2e/pages/25-2-gross-anatomy-of-urine-transport"}]}, {"title": "Précautions standard et complémentaires", "description": "B.1.a · S1 · 20 QCM corrigés", "courseId": "b1-precautions", "questions": [{"text": "Les précautions standard s’appliquent :", "options": ["Quel que soit le statut infectieux connu.", "À tous les lieux et soins concernés.", "Seulement après un résultat microbiologique positif.", "Seulement en réanimation.", "À tous les patients."], "answers": ["A", "B", "E"], "explanation": "Elles constituent le socle pour tous. Attendre un diagnostic infectieux laisserait sans protection une partie des situations à risque.", "id": 2600}, {"text": "Les précautions complémentaires :", "options": ["Remplacent toute hygiène des mains.", "Imposent tous les EPI pour toute visite sans analyse.", "S’organisent selon les procédures et l’équipe d’hygiène.", "S’ajoutent aux précautions standard.", "Sont adaptées au mode de transmission et à la situation."], "answers": ["C", "D", "E"], "explanation": "Les complémentaires ajoutent des barrières ciblées. Elles ne remplacent pas le socle standard et doivent être comprises dans leur contexte.", "id": 2601}, {"text": "Quelles situations font partie des indications d’hygiène des mains ?", "options": ["Uniquement quand une tache est visible.", "Avant un geste aseptique.", "Uniquement en début de poste.", "Après contact avec l’environnement du patient.", "Avant un contact avec le patient."], "answers": ["B", "D", "E"], "explanation": "Ces trois situations font partie des cinq indications ; s’y ajoutent après risque biologique et après contact avec le patient.", "id": 2602}, {"text": "Après un risque d’exposition à un liquide biologique :", "options": ["L’hygiène des mains reste indiquée.", "Les gants utilisés peuvent contaminer l’environnement.", "Les mêmes gants peuvent être gardés pour le patient suivant.", "Le port de gants peut supprimer toute indication d’hygiène.", "Le retrait des gants doit être suivi de l’hygiène prévue."], "answers": ["A", "B", "E"], "explanation": "Les gants ne sont pas une garantie d’absence de contamination des mains. Ils sont retirés à la fin de la tâche ; l’hygiène des mains reste nécessaire.", "id": 2603}, {"text": "Sur mains sèches et non visiblement souillées :", "options": ["La friction n’exige jamais le séchage du produit.", "Il faut toujours ajouter de l’eau au produit hydroalcoolique.", "Il faut couvrir toutes les zones selon la technique.", "Il faut respecter volume et durée prévus pour le produit.", "La friction hydroalcoolique est la technique de référence."], "answers": ["C", "D", "E"], "explanation": "Frictionner avec les conditions validées et laisser sécher. Ajouter de l’eau ou interrompre trop tôt modifie les conditions d’efficacité.", "id": 2604}, {"text": "Si les mains sont visiblement souillées :", "options": ["Les recouvrir de gants suffit à les nettoyer.", "Il faut adapter la suite aux indications et au protocole.", "Le nettoyage de la souillure est nécessaire.", "Une friction seule est systématiquement suffisante.", "Un lavage à l’eau et au savon est nécessaire."], "answers": ["B", "C", "E"], "explanation": "La souillure visible doit être retirée par lavage. Les gestes suivants dépendent de la situation ; couvrir les mains ne les nettoie pas.", "id": 2605}, {"text": "Lors des soins, les prérequis comprennent :", "options": ["Des avant-bras dégagés.", "Une alliance conservée dans toutes les situations.", "Des faux ongles indispensables.", "L’absence de bijoux aux mains et poignets.", "Des ongles courts."], "answers": ["A", "D", "E"], "explanation": "Ongles courts sans artifices, absence de bijoux et avant-bras dégagés permettent une hygiène des mains adaptée et limitent les obstacles.", "id": 2606}, {"text": "En précautions standard, les gants sont notamment indiqués pour :", "options": ["Toute entrée dans une chambre, même sans soin.", "Un contact avec muqueuse ou peau lésée.", "Toute prise de pouls sur peau saine sans autre risque.", "Un risque de contact avec sang ou liquide biologique.", "Une situation où les mains du professionnel sont lésées."], "answers": ["B", "D", "E"], "explanation": "Le choix dépend de l’exposition. Le contact simple avec peau saine et l’entrée sans geste ne justifient pas à eux seuls des gants en standard.", "id": 2607}, {"text": "Lors d’un passage d’un site contaminé à un site propre chez le même patient :", "options": ["Une désinfection de gants usagés permet toujours leur réemploi.", "Les transitions d’hygiène des mains sont à respecter.", "Les gants sont conservés car le patient ne change pas.", "Il faut changer les gants utilisés.", "Il faut organiser le soin pour limiter les contaminations."], "answers": ["B", "D", "E"], "explanation": "Un même patient peut présenter plusieurs sites à risques différents. Garder des gants contaminés transmettrait les agents vers le site propre.", "id": 2608}, {"text": "Une protection de la tenue est choisie :", "options": ["Sans tenir compte du soin.", "Selon l’étendue de l’exposition et le protocole.", "Pour pouvoir garder ensuite les mêmes gants partout.", "Avec un tablier imperméable pour certaines expositions.", "Selon le risque de soin mouillant ou souillant."], "answers": ["B", "D", "E"], "explanation": "La protection est adaptée à l’exposition. Elle ne rend pas les gants ni les autres surfaces propres après le soin.", "id": 2609}, {"text": "En cas de risque de projection vers le visage :", "options": ["Un masque adapté peut être nécessaire.", "Les lunettes personnelles protègent toujours autant qu’un équipement dédié.", "Une protection oculaire peut être nécessaire.", "Une protection de la tenue remplace forcément celle des yeux.", "L’analyse du risque guide les EPI."], "answers": ["A", "C", "E"], "explanation": "Les yeux et autres muqueuses doivent être protégés selon le risque. Les protections de tenue et du visage ne sont pas interchangeables.", "id": 2610}, {"text": "Pour une personne qui tousse, les mesures d’hygiène respiratoire peuvent inclure :", "options": ["Un masque indiqué et possible selon la situation.", "Tousser dans les mains puis toucher directement le matériel propre.", "Réutiliser les mêmes mouchoirs pour plusieurs patients.", "L’hygiène des mains après les sécrétions.", "Un mouchoir jetable ou le coude."], "answers": ["A", "D", "E"], "explanation": "Limiter la dispersion et la contamination des mains participe à la prévention. L’organisation et le masque éventuel s’adaptent au contexte.", "id": 2611}, {"text": "Un objet perforant à usage unique usagé doit être :", "options": ["Manipulé sans plier ou casser l’aiguille.", "Déposé d’abord sur le lit.", "Recapuchonné à la main avant d’être porté au local.", "Éliminé en respectant le niveau maximal du collecteur.", "Éliminé immédiatement dans un collecteur adapté proche."], "answers": ["A", "D", "E"], "explanation": "L’élimination immédiate sans dépose intermédiaire limite les accidents. Recapuchonner, plier ou dépasser le niveau augmente le risque.", "id": 2612}, {"text": "Après un accident exposant au sang :", "options": ["Il faut signaler immédiatement et demander un avis médical urgent.", "Il faut attendre la fin de poste pour tout avis.", "Les premiers soins adaptés doivent être réalisés.", "Il faut sécuriser le geste.", "Il faut volontairement faire saigner la plaie."], "answers": ["A", "C", "D"], "explanation": "La prise en charge est urgente. Premiers soins et signalement permettent une évaluation rapide ; faire saigner volontairement n’est pas recommandé.", "id": 2613}, {"text": "La gestion des excreta nécessite :", "options": ["Une hygiène des mains aux indications nécessaires.", "La manipulation de selles avec les mêmes gants que le matériel propre.", "Des protections adaptées à l’exposition.", "Une méthode validée d’entretien des contenants.", "Le rinçage systématique des bassins à la douchette."], "answers": ["A", "C", "D"], "explanation": "Les excreta peuvent disperser des contaminants. La douchette expose à des projections ; transitions propre/sale et méthode validée doivent être respectées.", "id": 2614}, {"text": "Un matériel utilisé pour plusieurs patients :", "options": ["Peut contribuer à la transmission indirecte s’il est contaminé.", "Doit être entretenu entre utilisations selon son risque.", "Peut être considéré propre uniquement parce qu’il n’a pas de tache.", "Nécessite le respect de sa notice.", "Ne concerne jamais les précautions standard."], "answers": ["A", "B", "D"], "explanation": "Un matériel partagé est un vecteur possible. Aspect visuel, notice et niveau de traitement sont des notions différentes.", "id": 2615}, {"text": "Les précautions complémentaires contact peuvent comporter :", "options": ["La suppression de tous les soins relationnels.", "Des mesures adaptées pour déplacements et tenue.", "Le port automatique de la même paire de gants tout le poste.", "Une organisation adaptée de la chambre.", "Du matériel dédié selon la situation."], "answers": ["B", "D", "E"], "explanation": "L’objectif est une barrière adaptée à la transmission tout en maintenant les soins. Les gants restent soumis aux indications et changements nécessaires.", "id": 2616}, {"text": "Concernant la prévention respiratoire :", "options": ["Une règle unique de masque suffit pour tous les agents et tous les soins.", "Les recommandations SF2H 2024 utilisent une analyse de risque plus large.", "Les termes historiques air/gouttelettes peuvent apparaître dans les supports.", "La ventilation, la proximité et le type de soin peuvent compter.", "Les précautions standard deviennent inutiles."], "answers": ["B", "C", "D"], "explanation": "L’approche récente dépasse la séparation simplifiée air/gouttelettes. Les mesures concrètes dépendent de l’agent, du soin et du protocole.", "id": 2617}, {"text": "Un FFP2 :", "options": ["N’est pas l’équivalent d’un masque chirurgical.", "Protège correctement même largement décollé du visage.", "Nécessite la vérification d’étanchéité prévue à sa mise en place.", "Doit être correctement adapté et porté.", "Peut être choisi sans aucune formation pour toutes les situations."], "answers": ["A", "C", "D"], "explanation": "Le niveau de protection dépend de l’équipement mais aussi de son ajustement. Un mauvais port réduit la protection attendue.", "id": 2618}, {"text": "L’isolement protecteur :", "options": ["A le même objectif unique que limiter la transmission depuis un patient infecté.", "Vise à protéger certains patients vulnérables d’agents extérieurs.", "S’adapte à l’immunodépression et au service.", "Dispense d’entretien et d’hygiène des mains.", "Doit être expliqué sans stigmatisation."], "answers": ["B", "C", "E"], "explanation": "Protecteur décrit l’objectif envers un patient vulnérable. Les mesures sont contextualisées et ne remplacent ni l’hygiène ni la relation de soins.", "id": 2619}], "overview": [["Repère 1", "Standard : pour tous ; complémentaires : en plus, selon le risque."], ["Repère 2", "Les gants ne remplacent pas l’hygiène des mains."], ["Repère 3", "Choisir les protections selon le soin et l’exposition."], ["Repère 4", "AES : premiers soins et avis médical urgent, avec signalement."], ["Repère 5", "Isolement protecteur : protéger un patient vulnérable des agents extérieurs."]], "references": [{"title": "SF2H · Précautions standard", "url": "https://www.sf2h.net/k-stock/data/uploads/2017/06/HY_XXV_PS_versionSF2H.pdf"}, {"title": "SF2H · Prévention : repères pédagogiques 2025", "url": "https://www.sf2h.net/k-stock/data/uploads/2025/05/prevenir_la_transmisison_des_infections_formateurs-v30-04-25.pdf"}, {"title": "SF2H · Transmission respiratoire 2024", "url": "https://www.sf2h.net/k-stock/data/uploads/2024/reco_respiratoire/Prevention_transmission_voie_respiratoire_RECOS_SF2H.pdf"}, {"title": "INRS · Accident exposant au sang", "url": "https://www.inrs.fr/actualites/accidents-exposant-au-sang-et-aux-liquides-biologiques.html"}]}, {"title": "Linge, déchets, désinfection et stérilisation", "description": "B.1.a · S1 · 20 QCM corrigés", "courseId": "b1-environnement", "questions": [{"text": "Séparer les circuits propre et sale permet :", "options": ["De guider rangement et transport.", "De limiter les contaminations croisées.", "De rendre inutile l’hygiène des mains.", "De garantir qu’une surface sans tache est stérile.", "De structurer la succession des tâches."], "answers": ["A", "B", "E"], "explanation": "La séparation est une mesure d’organisation complémentaire aux gestes d’hygiène. Elle ne garantit pas à elle seule la propreté microbiologique ou la stérilité.", "id": 2700}, {"text": "Le linge propre doit être :", "options": ["Protégé dans un rangement adapté.", "Mélangé au linge utilisé si celui-ci n’a pas de tache.", "Manipulé avec des mains propres.", "Préservé des contacts avec le sale.", "Rangé sur le sol de la chambre."], "answers": ["A", "C", "D"], "explanation": "Le linge propre peut être recontaminé lors du stockage et de la manipulation. L’absence de tache sur le linge utilisé ne suffit pas à le rendre propre.", "id": 2701}, {"text": "Lors de la collecte du linge sale :", "options": ["Le déposer d’abord au sol pour le compter.", "Éviter de le plaquer contre la tenue.", "L’ensacher selon le circuit au plus près du soin.", "Éviter de le secouer.", "Le trier ensuite en fouillant tous les sacs collectés."], "answers": ["B", "C", "D"], "explanation": "Ces mesures limitent dispersion et exposition. Le tri et la collecte suivent le circuit prévu, sans secouer ni déposer au sol.", "id": 2702}, {"text": "Un drap réutilisable souillé :", "options": ["Peut nécessiter des EPI adaptés lors de sa manipulation.", "Suit le circuit de linge de l’établissement.", "Est automatiquement un déchet à éliminer définitivement.", "Doit systématiquement être remis directement dans le stock propre.", "Peut relever de la blanchisserie adaptée."], "answers": ["A", "B", "E"], "explanation": "Souillure ne transforme pas automatiquement un textile réutilisable en déchet. Le circuit et les protections répondent au risque de manipulation.", "id": 2703}, {"text": "Les déchets d’activité de soins :", "options": ["Doivent être triés selon leur nature et leur risque.", "Peuvent relever de filières spécifiques.", "Ne sont pas tous automatiquement infectieux.", "Sont définis comme DASRI uniquement par leur couleur.", "Doivent tous être mélangés dans un seul sac."], "answers": ["A", "B", "C"], "explanation": "La filière dépend du risque et de la nature. La couleur est un repère, pas le critère suffisant de classement.", "id": 2704}, {"text": "Une aiguille destinée à l’abandon, même sans contact avec un liquide biologique :", "options": ["Relève d’un collecteur adapté aux perforants.", "Peut être jetée en vrac dans un sac ordinaire.", "Expose à une blessure.", "Doit être manipulée selon les règles du collecteur.", "Doit obligatoirement être cassée à la main."], "answers": ["A", "C", "D"], "explanation": "Le caractère perforant impose le collecteur adapté, indépendamment du contact préalable avec un produit biologique. Ne pas casser ou jeter en vrac.", "id": 2705}, {"text": "Pour utiliser un collecteur de perforants :", "options": ["Tasser les aiguilles à la main.", "Respecter son niveau maximal.", "Respecter ses règles de fermeture.", "Récupérer un objet en introduisant les doigts.", "Le placer de façon stable et proche du geste."], "answers": ["B", "C", "E"], "explanation": "Stabilité, proximité et respect de remplissage et fermeture préviennent les blessures. Tasser ou récupérer un objet est dangereux.", "id": 2706}, {"text": "Les déchets chimiques ou médicamenteux :", "options": ["Doivent toujours être vidés dans le lavabo.", "Ne sont pas à mélanger par défaut avec tous les autres déchets.", "Peuvent demander une filière dédiée.", "Sont forcément du linge sale.", "Doivent être identifiés selon les consignes."], "answers": ["B", "C", "E"], "explanation": "Le tri dépend de la nature, notamment chimique ou médicamenteuse. Les filières évitent une élimination inadaptée.", "id": 2707}, {"text": "Le nettoyage :", "options": ["Prépare un traitement ultérieur approprié.", "Est toujours identique à une antisepsie cutanée.", "Retire des salissures.", "Peut réduire la charge microbienne.", "Garantit à lui seul la stérilité de tout instrument."], "answers": ["A", "C", "D"], "explanation": "Nettoyer élimine des salissures mais ne garantit pas la stérilité. C’est un préalable essentiel aux traitements exigeants.", "id": 2708}, {"text": "La désinfection :", "options": ["A une activité dépendant du produit et du procédé.", "Ne doit pas être confondue avec la stérilisation.", "Concerne des milieux inertes dans des conditions définies.", "Élimine nécessairement toutes les spores dans toute situation.", "Permet d’appliquer n’importe quel produit de surface sur la peau."], "answers": ["A", "B", "C"], "explanation": "Le niveau d’action varie. Désinfection et stérilisation ne sont pas équivalentes ; un produit de surface n’est pas automatiquement un antiseptique.", "id": 2709}, {"text": "L’antisepsie :", "options": ["Utilise un produit adapté à cet usage.", "Est identique à l’usage de tout détergent pour sols.", "Ne justifie pas l’application d’un produit de surface sur la peau.", "Concerne des tissus vivants.", "Supprime toute nécessité de méthode aseptique."], "answers": ["A", "C", "D"], "explanation": "L’usage sur le vivant impose un produit et des conditions adaptés. Antisepsie et asepsie se complètent mais ne désignent pas le même principe.", "id": 2710}, {"text": "L’asepsie vise :", "options": ["À organiser un geste pour protéger le site.", "À contaminer volontairement une plaie.", "À éviter l’introduction de contaminants.", "À supprimer le nettoyage de tout matériel.", "À utiliser du matériel adapté au risque."], "answers": ["A", "C", "E"], "explanation": "L’asepsie est un ensemble de moyens de prévention. Elle inclut l’organisation et le matériel, et ne remplace pas les traitements nécessaires.", "id": 2711}, {"text": "Le bionettoyage :", "options": ["Peut suivre une procédure validée à étapes séparées.", "Peut utiliser un détergent-désinfectant validé selon le contexte.", "Permet d’ignorer toutes les salissures visibles.", "Est toujours une stérilisation.", "Associe une méthode de nettoyage et de réduction microbienne."], "answers": ["A", "B", "E"], "explanation": "Plusieurs méthodes sont possibles mais leurs conditions doivent être respectées. Une salissure peut compromettre la désinfection.", "id": 2712}, {"text": "Pour utiliser un produit désinfectant :", "options": ["Respecter sa concentration prévue.", "Le diluer librement pour économiser le produit.", "Respecter le temps de contact.", "L’essuyer immédiatement dans tous les cas.", "Vérifier la compatibilité avec le support."], "answers": ["A", "C", "E"], "explanation": "Concentration, temps et compatibilité sont des conditions d’efficacité et de sécurité. Les modifications improvisées peuvent rendre le produit inadapté.", "id": 2713}, {"text": "Concernant le mélange de produits d’entretien :", "options": ["Il ne doit pas être improvisé.", "Il peut provoquer des réactions dangereuses.", "Il est obligatoire pour tous les détergents-désinfectants.", "Il peut modifier l’efficacité.", "Il améliore toujours la désinfection."], "answers": ["A", "B", "D"], "explanation": "Des mélanges peuvent dégager des gaz toxiques ou altérer l’activité. Utiliser les produits selon leur notice, sans mélange improvisé.", "id": 2714}, {"text": "Un dispositif critique, au sens de la classification du risque :", "options": ["Pénètre un tissu normalement stérile ou le système vasculaire.", "Doit être stérile au moment de son utilisation.", "Exige un traitement approprié et une barrière préservée.", "Peut être rendu stérile par un simple essuyage non validé.", "Est tout objet touchant uniquement une peau intacte."], "answers": ["A", "B", "C"], "explanation": "L’usage critique impose la stérilité. Un essuyage ne remplace pas un procédé validé et les contrôles de l’état stérile.", "id": 2715}, {"text": "Un dispositif semi-critique et un non critique se distinguent notamment ainsi :", "options": ["Le traitement dépend aussi des exigences spécifiques et de la notice.", "Non critique signifie ne jamais nettoyer.", "Tous deux sont toujours traités comme de simples meubles.", "Non critique : contact avec peau intacte dans cette classification.", "Semi-critique : contact avec muqueuse ou peau non intacte."], "answers": ["A", "D", "E"], "explanation": "La classification oriente le niveau de traitement. Elle ne dispense pas des notices, des exigences spécifiques ou de l’entretien des non critiques.", "id": 2716}, {"text": "La stérilisation :", "options": ["Vise un état exempt de micro-organismes viables, spores comprises.", "Est garantie par l’absence de taches visibles.", "N’est pas un simple lavage.", "N’exige aucun nettoyage préalable.", "Est un procédé validé."], "answers": ["A", "C", "E"], "explanation": "La stérilisation exige un procédé et une chaîne maîtrisés. Le nettoyage est un préalable ; un aspect propre ne prouve pas l’état stérile.", "id": 2717}, {"text": "Avant d’utiliser un paquet stérile :", "options": ["Utiliser un paquet déchiré si le matériel paraît propre.", "Considérer qu’une couleur d’indicateur suffit à tout prouver.", "Vérifier l’intégrité du conditionnement.", "Vérifier l’absence d’humidité et la validité selon la procédure.", "Vérifier les éléments de traçabilité attendus."], "answers": ["C", "D", "E"], "explanation": "Le conditionnement préserve l’état stérile. Intégrité, état sec, validité et contrôle du circuit comptent ; un indicateur seul ne valide pas toute la chaîne.", "id": 2718}, {"text": "Un dispositif à usage unique :", "options": ["Ne doit pas être retraité dans le service comme un réutilisable.", "Peut être réutilisé dès qu’il n’a pas de tache.", "N’est pas rendu réutilisable par un simple rinçage.", "Doit être utilisé conformément à sa notice.", "Est toujours une pièce de linge."], "answers": ["A", "C", "D"], "explanation": "Usage unique et réutilisable relèvent de règles différentes. Une apparence propre ou un rinçage ne modifient pas la destination du dispositif.", "id": 2719}], "overview": [["Repère 1", "Propre et sale : circuits, rangement et manipulations séparés."], ["Repère 2", "Linge sale : ne pas secouer, ne pas poser au sol, ensacher au point de soin."], ["Repère 3", "Déchets : tri selon risque et filière, pas tous en DASRI."], ["Repère 4", "Nettoyage ≠ désinfection ≠ antisepsie ≠ stérilisation."], ["Repère 5", "Stérilisation : procédé validé, nettoyage préalable, traçabilité et barrière intacte."]], "references": [{"title": "Ministère de la Santé · Déchets de soins et guide 2025", "url": "https://sante.gouv.fr/soins-et-maladies/qualite-securite-et-pertinence-des-soins/securite-des-prises-en-charge/reglementation-de-securite-sanitaire-dans-les-etablissements-de-sante/article/elimination-des-dechets-d-activites-de-soins-a-risque-infectieux"}, {"title": "CDC · Classification du risque des dispositifs", "url": "https://www.cdc.gov/infection-control/hcp/disinfection-sterilization/rational-approach.html"}, {"title": "CDC · Définitions des procédés", "url": "https://www.cdc.gov/infection-control/hcp/disinfection-sterilization/glossary.html"}, {"title": "CPias Nouvelle-Aquitaine · Fiches pratiques, dont linge et environnement", "url": "https://www.cpias-nouvelle-aquitaine.fr/actualites/les-fiches-pratiques-sur-la-maitrise-du-risque-infectieux-en-esms-de-nouveau-accessibles/"}]}];
